std::map<PII, int> M;
std::vector<std::vector<PII> > G(MAX);
bool U[MAX];
bool ok;

void dfs(int v, int p, int dir) {
    U[v] = 1;
    int bal = 0;
    ITER(i, G[v]) {
        int x = i->first, y = i->second;
        if(x == p && y == -dir) continue;
        if(!U[x]) {
            dfs(x, v, y);
            bal += M[MP(x, v)] - M[MP(v, x)];
        }
    }
    ITER(i, G[v]) {
        int x = i->first, y = i->second;
        if(x == p && y == -dir) continue;
        if(U[x]) M[MP(v, x)] = M[MP(x, v)] + bal;
        else ok = 0;
    }
}

