struct Tour {
    int to, hour, duration, used;
    Tour(int _to, int _hour, int _duration) : to(_to), hour(_hour), duration(_duration), used(0) {}
};

ll totalUsed = 0;
vector<vector<Tour>> graph;
int n;
ll vis[1000001];

bool reachDFS(int u, int v, int t) {
    if (u == v) return true;
    if (vis[u] == t) return false;
    vis[u] = t;
    for (auto& tour : graph[u]) {
        if (!tour.used && reachDFS(tour.to, v, t)) return true;
    }
    return false;
}

bool reachablePast(int u, int v, int t) {
    memset(vis, 0, sizeof vis);
    return reachDFS(u, v, t + 1);
}

int endTime(int start, int duration) { return start + duration; }

ll dfs(int u, int t) {
    ll ans = OO;
    for (auto& tour : graph[u]) {
        if (tour.hour >= t && !tour.used) {
            tour.used = 1;
            totalUsed++;
            if (reachablePast(tour.to, n - 1, endTime(tour.hour, tour.duration))) {
                minify(ans, dfs(tour.to, endTime(tour.hour, tour.duration)));
            }
            tour.used = 0;
            totalUsed--;
        }
    }
    if (ans == OO) return t;
    return ans;
}

