struct dist {
    int d, index;
    set<int> surround;
    bool operator<(const dist& other) const {
        if (d != other.d)
            return d > other.d;
        if (surround.size() != other.surround.size())
            return surround.size() < other.surround.size();
        return index > other.index;
    }
};

int main() {
    int T, n, m, u, v;
    scanf("%d", &T);
    for (int t = 1; t <= T; t++) {
        scanf("%d %d", &n, &m);
        set<int> graph[n];
        for (int i = 0; i < m; i++) {
            scanf("%d %d", &u, &v);
            graph[u].insert(v);
            graph[v].insert(u);
        }
        dist d[n];
        for (int i = 0; i < n; i++) {
            d[i].index = i;
            d[i].d = n + 1;
        }
        set<dist> next;
        for (int i = 0; i < n; i++)
            if (i != 0)
                next.insert(d[i]);
        d[0].d = 0;
        next.insert(d[0]);
        while (!next.empty()) {
            dist cur = *next.begin();
            next.erase(next.begin());
            for (int neighbor : graph[cur.index]) {
                dist& nei = d[neighbor];
                if (cur.d + 1 < nei.d) {
                    next.erase(nei);
                    nei.d = cur.d + 1;
                    nei.surround = cur.surround;
                    nei.surround.insert(cur.index);
                    next.insert(nei);
                } else if (cur.d + 1 == nei.d)
                    nei.surround.insert(cur.index);
            }
        }
        int r = d[1].surround.size();
        printf("Case %d: %d %d\n", t, d[1].d, r);
        fflush(stdout);
    }
    return 0;
}
