int A, V, M;
double dp[22];

double acc(int n) {
    if(EQ(dp[n], -1.0)) {
        if(n == 0) dp[n] = 1.0;
        else dp[n] = acc(n - 1) * (1.0 * A / V);
    }
    return dp[n];
}

double sub(int n, int b) {
    if(n == 0 && b == 0) return 1.0;
    if(b < 0) return 0.0;
    if(EQ(dp[n * 22 + b], -1.0)) {
        double res = 0.0;
        REP(i, b + 1) {
            res += sub(n - 1, b - i) * acc(i) * (1.0 * (V - A) / V);
        }
        dp[n * 22 + b] = res;
    }
    return dp[n * 22 + b];
}

void solve() {
    std::cin >> A >> V >> M;
    MEMSET(dp, -1.0);
    std::cout << sub(M, V) << "\n";
}

