typedef double ld;
const ld EPS = 1e-6;
const ld INF = 1e9;
const int MAXN = 3000;
const int MAXS = 100;

struct pt {
    ld x, y, z;
    pt() {}
    pt(ld x, ld y, ld z) : x(x), y(y), z(z) {}
};

inline ld sq(ld a) { return a * a; }
inline ld norm(const pt &p) { return sq(p.x) + sq(p.y) + sq(p.z); }
inline ld abs(const pt &p) { return sqrt(norm(p)); }

pt operator + (const pt &a, const pt &b) { return pt(a.x + b.x, a.y + b.y, a.z + b.z); }
pt operator - (const pt &a, const pt &b) { return pt(a.x - b.x, a.y - b.y, a.z - b.z); }
pt operator * (const pt &a, const ld &v) { return pt(a.x * v, a.y * v, a.z * v); }

pt cross(const pt &a, const pt &b) { return pt(a.y * b.z - a.z * b.y, a.z * b.x - a.x * b.z, a.x * b.y - a.y * b.x); }
ld dot(const pt &a, const pt &b) { return a.x * b.x + a.y * b.y + a.z * b.z; }

int N;
int S;
pt P[MAXN], V[MAXN];
ld M;
ld dist[MAXN];
bool vis[MAXN];

bool dijkstra() {
    memset(vis, 0, sizeof vis);
    for (int i = 0; i < N; i++) dist[i] = INF;
    dist[0] = 0;

    priority_queue<pair<ld, int>, vector<pair<ld, int>>, greater<pair<ld, int>>> pq;
    pq.push(make_pair(0, 0));

    while (!pq.empty()) {
        int u = pq.top().second;
        pq.pop();
        if (vis[u]) continue;
        vis[u] = true;

        for (int v = 0; v < N; v++) {
            if (u == v) continue;
            ld d = abs(P[v] - P[u]);
            for (int j = 0; j <= S; j++) {
                ld t = j * 1.0 / S;
                d = min(d, abs(P[v] + V[v] * t - (P[u] + V[u] * t)) - M);
            }
            if (dist[v] > dist[u] + d) {
                dist[v] = dist[u] + d;
                pq.push(make_pair(dist[v], v));
            }
        }
    }

    return dist[1] < INF;
}

ld binary_search() {
    ld lo = 0, hi = INF;
    for (int iter = 0; iter < 100; iter++) {
        M = (lo + hi) / 2;
        if (dijkstra()) hi = M;
        else lo = M;
    }
    return hi;
}

int main() {
    int T;
    scanf("%d", &T);
    while (T--) {
        scanf("%d %d", &N, &S);
        for (int i = 0; i < N; i++) scanf("%lf %lf %lf", &P[i].x, &P[i].y, &P[i].z);
        for (int i = 0; i < N; i++) scanf("%lf %lf %lf", &V[i].x, &V[i].y, &V[i].z);
        printf("%.7f\n", binary_search());
    }
    return 0;
}
