inline int dpf(int np, int h)
{
    if (h == 0)
        return np;
    if (np == n)
        return 1e9;
    int &res = far[np][h];
    if (res != -1)
        return res;
    res = 1e9;
    FOR(d, 0, 9)
    {
        if (lastn[np][d] != -1)
        {
            res = min(res, dpf(lastn[np][d] + 1, h - val[d]));
        }
    }
    return res;
}

