const int INF = 999999999;
typedef long long ll;
const int dx[] = {0, -1, 1, 0};
const int dy[] = {-1, 0, 0, 1};
int W, H, X, Y;
int fld[10000][10][10];

int saiki(int r) {
    if (!fld[r][X][Y]) return 0;
    bool ok = false;
    rep(i, 4) {
        int x = X + dx[i], y = Y + dy[i];
        if (0 <= x && x < W && 0 <= y && y < H && fld[r][x][y]) {
            ok = true;
            goto dmp;
        }
    }
    return INF;
dmp:
    int res = 0;
    rep(i, 4) {
        int x = X + dx[i], y = Y + dy[i];
        if (0 <= x && x < W && 0 <= y && y < H) {
            memcpy(fld[r + 1], fld[r], sizeof(fld[r]));
            rep(j, W) rep(k, H) {
                if (j == X && k == Y) {
                    fld[r + 1][x][y] += fld[r][j][k];
                    fld[r + 1][j][k] = 0;
                } else {
                    int nx = j + dx[i], ny = k + dy[i];
                    if (0 <= nx && nx < W && 0 <= ny && ny < H) fld[r + 1][nx][ny] = max(fld[r + 1][nx][ny], fld[r][j][k]);
                }
            }
            rep(j, W) rep(k, H) if (fld[r + 1][j][k] < 0) fld[r + 1][j][k] = 0;
            res = max(res, 1 + saiki(r + 1));
        }
    }
    return res;
}

