        int res = saiki(0);
        printf("Case %d: %s\n", t + 1, res >= INF ? "forever" : res < 0 ? "impossible" : res > 0 ? (res > 1 ? "after %d days" : "after 1 day", max(1, res - 1)) : "no day");
    }
    return 0;
}
