void eGCD(intT a, intT b, intT &x, intT &y) {
    if(b == 0) {
        x = 1;
        y = 0;
        return;
    }
    intT x1, y1;
    eGCD(b, a % b, x1, y1);
    x = y1;
    y = x1 - y1 * (a / b);
}

