            int r = rand() % sum;
            for (int j = 0; j < ne[i].size(); j++) {
                if (r < size[ne[i][j]]) {
                    sel = ne[i][j];
                    break;
                }
                r -= size[ne[i][j]];
            }
        }
        q[pt++] = 'a' + i;
        if (sel) deal();
        else return;
    }
