const int MAX = 1000000;
const int ITER = 13;
const int NEAR = 9;

int n;
struct point { double x, y; } a[MAX];
double pi = acos(-1.0);
point A, B;

bool cmp(const point &P, const point &Q) {
    double v = (P.x - A.x) * (B.y - A.y) - (P.y - A.y) * (B.x - A.x);
    if (v == 0) return ((P.x - A.x) * (P.x - A.x) + (P.y - A.y) * (P.y - A.y)) < ((Q.x - A.x) * (Q.x - A.x) + (Q.y - A.y) * (Q.y - A.y));
    return v < 0;
}

double dist(int i, int j) {
    double dx = a[i].x - a[j].x;
    double dy = a[i].y - a[j].y;
    return sqrt(dx * dx + dy * dy);
}

int main() {
    int T;
    cin >> T;
    while (T--) {
        cin >> n;
        for (int i = 0; i < n; i++) cin >> a[i].x >> a[i].y;
        double ret = 1e15;
        for (int it = 0; it < ITER; it++) {
            double alpha = pi * it / ITER;
            A.x = cos(alpha);
            A.y = sin(alpha);
            B.x = -A.y;
            B.y = A.x;
            sort(a, a + n, cmp);
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < min(i + NEAR, n); j++) {
                    for (int k = j + 1; k < min(j + NEAR, n); k++) {
