    if (!f.count(x)) f[x] = cnt++;
    return f[x];
}

void dfs(int step, int s) {
    if (found) return;
    if (step == n) {
        found = true;
        return;
    }
    int mask = 0;
    for (int i = 0; i < m; i++)
        if (!flag[i])
            for (int j = 0; j < m; j++)
                if (flag[j] && g[j][i]) mask |= (1 << i);
    for (int i = 0; i < m; i++)
        if (!(s & (1 << i)) && !(mask & (1 << i)) && now[i]) {
            for (int j = 0; j < m; j++)
                if (flag[j] && g[j][i]) now[j]--;
            flag[i] = true;
            now[i]--;
            ans[step] = a[i];
            if (!pool[s | (1 << i)]) {
                pool[s | (1 << i)] = true;
                dfs(step + 1, s | (1 << i));
            }
            now[i]++;
            for (int j = 0; j < m; j++)
                if (flag[j] && g[j][i]) now[j]++;
            flag[i] = false;
        }
}

void work() {
    memset(flag, 0, sizeof flag);
    memset(now, 0, sizeof now);
    memset(pool, 0, sizeof pool);
    found = false;
    cin >> n >> m;
    for (int i = 0; i < m; i++) {
        int x;
