        now[i] = 1;
    }
    for (int i = 0; i < m; i++)
        for (int j = 0; j < m; j++) {
            cin >> g[i][j];
            now[j] += g[i][j];
        }
    dfs(0, 0);
    if (found) {
        for (int i = 0; i < n; i++) cout << f[ans[i]] << " ";
        cout << "\n";
    } else {
        cout << "IMPOSSIBLE\n";
    }
}

