long long maxV = -1, maxCnt = 0;
const int mod = 1e9 + 7;

void go(int t) {
    if (t == m) {
        map<string, int> cnt;
        long long sum = 0;
        for (int i = 0; i < m; i++) {
            set<string> st;
            for (int j = 0; j < s[i].size(); j++) {
                for (int k = j + 1; k <= s[i].size(); k++) {
                    st.insert(s[i].substr(j, k - j));
                }
            }
            sum += st.size();
            for (auto x : st) {
                cnt[x]++;
            }
        }
        for (auto x : cnt) {
            sum -= (x.second * (x.second - 1)) / 2;
        }
        sum %= mod;
        if (sum > maxV) {
            maxV = sum;
            maxCnt = 1;
        } else if (sum == maxV) {
            maxCnt++;
        }
        return;
    }
    for (int i = 0; i < n; i++) {
        a[t] = i;
        go(t + 1);
    }
}

