int dp[600][600];
int M = 100003;

bool poss(int pos, int i, int mark) {
    return abs(pos - mark) >= abs(pos - i);
}

int permut(int D) {
    int res = 1;
    for (int i = 1; i <= D; i++)
        res = (res * i) % M;
    return res;
}

int cal(int pos, int i, int mark) {
    int N = abs(mark - pos);
    int D = abs(pos - i);
    return (permut(N) - permut(N - D)) % M;
}

int solve(int mark, int pos) {
    if (dp[mark][pos] != -1)
        return dp[mark][pos];
    int ans = 0;
    for (int i = 1; i < pos; i++) {
        if (poss(pos, i, mark))
            ans = (ans + cal(pos, i, mark) * solve(pos, i)) % M;
    }
    dp[mark][pos] = ans;
    return ans;
}

int main() {
    int T;
    cin >> T;
    while (T--) {
        int n;
        cin >> n;
        memset(dp, -1, sizeof(dp));
        dp[n][0] = 1;
        int ans = 0;
        for (int i = 1; i < n; i++)
            ans = (ans + solve(n, i)) % M;
        cout << ans << endl;
    }
    return 0;
}
