struct tnode {
    int sx, sy, lx, ly, cnt;
    tnode *L, *R;
    tnode(int a, int b, int c, int d) {
        sx = a;
        sy = b;
        lx = c;
        ly = d;
        cnt = 0;
        L = R = NULL;
    }
};

int IDX[100005];
int N, REQ[100005][3];

bool good(tnode *n, int y, int x) {
    return n->sx < x && x <= n->lx && n->sy < y && y <= n->ly;
}

void addpoint(tnode *n, int y, int x) {
    n->cnt++;
    if (n->sx == n->lx && n->sy == n->ly)
        return;
    if (!n->L)
        n->L = new tnode(n->sx, n->sy, (n->sx + n->lx) / 2, (n->sy + n->ly) / 2);
    if (!n->R)
        n->R = new tnode((n->sx + n->lx) / 2, (n->sy + n->ly) / 2, n->lx, n->ly);
    if (good(n->L, y, x))
        addpoint(n->L, y, x);
    else
        addpoint(n->R, y, x);
}

int cntpoint(tnode *n, int y, int x) {
    if (!n || n->lx < n->sx || n->ly < n->sy)
        return 0;
    if (n->lx <= x && n->ly <= y)
        return n->cnt;
    return cntpoint(n->L, y, x) + cntpoint(n->R, y, x);
}

