bool force(int i, int j, char beam) {
    if (i < 0 || i >= nRows || j < 0 || j >= nCols || forcedGrid[i][j] != '.' || grid[i][j] == '#') {
        return false;
    }
    forcedGrid[i][j] = beam;
    return true;
}

bool isBeam(char c) {
    return c == '|' || c == '-';
}

char see(int r, int c, int rd, int cd) {
    while (r >= 0 && r < nRows && c >= 0 && c < nCols && grid[r][c] != '#') {
        r += rd;
        c += cd;
    }
    return (r < 0 || r >= nRows || c < 0 || c >= nCols) ? '#' : grid[r][c];
}

char rotate(char c) {
    return c == '|' ? '-' : '|';
}

int check(const vector<char> & lit) {
    int r = lit[0] - 'A', c = lit[1] - '1', type = lit[2];
    char beam = (type == '|') ? '|' : '-';
    if (!force(r, c, beam)) {
        return -1;
    }
    char res = see(r, c, (beam == '|') ? 1 : 0, (beam == '|') ? 0 : 1);
    forcedGrid[r][c] = '.';
    return (res == '#') ? 1 : 0;
}

bool solve() {
    vector<vector<char>> literals;
    for (int i = 0; i < nRows; i++) {
        for (int j = 0; j < nCols; j++) {
            if (grid[i][j] != '.') {
                literals.push_back(vector<char>{(char)(i + 'A'), (char)(j + '1'), grid[i][j]});
            }
        }
    }

    for (int mask = 0; mask < (1 << literals.size()); mask++) {
        memset(forcedGrid, '.', sizeof(forcedGrid));
        bool valid = true;
        for (int i = 0; i < literals.size(); i++) {
            if (mask & (1 << i)) {
                int res = check(literals[i]);
                if (res == -1) {
                    valid = false;
                    break;
                } else if (res == 0) {
                    char beam = rotate(literals[i][2]);
                    if (!force(literals[i][0] - 'A', literals[i][1] - '1', beam)) {
                        valid = false;
                        break;
                    }
                }
            }
        }
        if (valid) {
            for (int i = 0; i < nRows; i++) {
                for (int j = 0; j < nCols; j++) {
                    if (forcedGrid[i][j] == '.') {
                        char res = see(i, j, 1, 0);
                        if (res == '#') {
                            res = see(i, j, 0, 1);
                            if (res == '#') {
                                valid = false;
                                break;
                            }
                        }
                    }
                }
                if (!valid) {
                    break;
                }
            }
        }
        if (valid) {
            for (int i = 0; i < nRows; i++) {
                cout << forcedGrid[i] << '\n';
            }
            return true;
        }
    }
    cout << "impossible\n";
    return false;
}

