int H, W, M;
int he[12][12], wa[12][12];

bool inrange(int y, int x) {
    return 0 <= y && y < H && 0 <= x && x < W;
}

int accwa(int y, int x) {
    if (inrange(y, x)) return wa[y][x];
    return 0;
}

bool walled(int y, int x, bool vis[12][12]) {
    if (!inrange(y, x) || vis[y][x] || accwa(y, x)) return false;
    vis[y][x] = true;
    bool ret = true;
    REP(dy, 2) REP(dx, 2) {
        ret = ret && walled(y + dy * (dy ? -1 : 1), x + dx * (dx ? -1 : 1), vis);
    }
    return ret;
}

void fill() {
    MEMSET(wa, 0);
    REP(y, H) REP(x, W) {
        bool vis[12][12];
        MEMSET(vis, 0);
        wa[y][x] = walled(y, x, vis);
    }
}

void erose() {
    REP(y, H) REP(x, W) {
        int nh = he[y][x];
        REP(dy, 2) REP(dx, 2) {
            if (inrange(y + dy * (dy ? -1 : 1), x + dx * (dx ? -1 : 1))) {
                int ny = y + dy * (dy ? -1 : 1);
                int nx = x + dx * (dx ? -1 : 1);
                if (!wa[ny][nx] && he[ny][nx] < he[y][x] - M) {
                    nh = max(nh - M, he[ny][nx] + 1);
                }
            }
        }
        he[y][x] = nh;
    }
}

void solve() {
    scanf("%d%d%d", &H, &W, &M);
    REP(y, H) REP(x, W) scanf("%d", &he[y][x]);
    int cnt = 0;
    while (true) {
        fill();
        bool zero = true;
        REP(y, H) REP(x, W) if (he[y][x]) zero = false;
        if (zero) break;
        erose();
        cnt++;
    }
    printf("%d\n", cnt);
}

