#define MAX 101

struct node {
    int begin, end;
    bool flag;
    bool operator<(const node &other) const {
        return (begin < other.begin) || (begin == other.begin && end < other.end);
    }
};

node sna[MAX], snb[MAX];
int countna, countnb, na, nb, t;

bool cmp(const node &a, const node &b) {
    return a < b;
}

void find(node ins, int type) {
    if (type == 0) {
        for (int i = 0; i < nb; i++) {
            if (!snb[i].flag && snb[i].begin >= ins.end + t) {
                snb[i].flag = true;
                find(snb[i], 0);
            }
        }
    } else {
        for (int i = 0; i < na; i++) {
            if (!sna[i].flag && sna[i].begin >= ins.end + t) {
                sna[i].flag = true;
                find(sna[i], 1);
            }
        }
    }
}

int main() {
    std::ifstream infile("B-large.in");
    std::ofstream outfile("B-large.out");
    int n;
    infile >> n;
    for (int i = 0; i < n; i++) {
        infile >> t >> na >> nb;
        for (int j = 0; j < na; j++) {
            infile >> sna[j].begin >> sna[j].end;
            sna[j].flag = false;
        }
        for (int j = 0; j < nb; j++) {
            infile >> snb[j].begin >> snb[j].end;
            snb[j].flag = false;
        }
        std::sort(sna, sna + na, cmp);
        std::sort(snb, snb + nb, cmp);
        for (int j = 0; j < na; j++) {
            if (!sna[j].flag) {
                sna[j].flag = true;
                find(sna[j], 1);
            }
        }
        for (int j = 0; j < nb; j++) {
            if (!snb[j].flag) {
                snb[j].flag = true;
                find(snb[j], 0);
            }
        }
        countna = 0;
        countnb = 0;
        for (int j = 0; j < na; j++) {
            if (!sna[j].flag) {
                countna++;
            }
        }
        for (int j = 0; j < nb; j++) {
            if (!snb[j].flag) {
                countnb++;
            }
        }
        outfile << "Case #" << i + 1 << ": " << countna << " " << countnb << std::endl;
    }
    infile.close();
    outfile.close();
