int c, n, m, f, AC;
vector<vector<char>> s;

bool dfs(int x, int y, int w, int c, int p) {
    if (x >= n || y >= m || s[x][y] == '#') return false;
    if (x == n - 1 && y == m - 1) {
        if (w + c <= f) {
            AC = min(AC, w + c);
            return true;
        }
        return false;
    }
    bool res = false;
    if (p != 1 && s[x][y + 1] != '#') {
        int cost = (p == 2) ? c : 0;
        res |= dfs(x, y + 1, w + cost, c, 2);
    }
    if (p != 2 && s[x][y - 1] != '#') {
        int cost = (p == 1) ? c : 0;
        res |= dfs(x, y - 1, w + cost, c, 1);
    }
    if (s[x + 1][y] != '#') {
        res |= dfs(x + 1, y, w + c, c, 0);
    }
    return res;
}

int main() {
    cin >> c;
    for (int i = 1; i <= c; i++) {
        cin >> n >> m >> f;
        s.assign(n, vector<char>(m));
        for (int j = 0; j < n; j++) {
            for (int k = 0; k < m; k++) {
                cin >> s[j][k];
            }
        }
        AC = -1;
        dfs(0, 0, 0, 0, 0);
        if (AC == -1) {
            cout << "Case #" << i << ": No" << endl;
        } else {
            cout << "Case #" << i << ": Yes " << AC << endl;
        }
    }
    return 0;
}
