int r, c, a[10][10], b[10][10], dx[9] = {0, 0, 1, -1, 0, -1, -1, 1, 1}, dy[9] = {0, 1, 0, 0, -1, -1, 1, -1, 1};

void Load() {
    ifstream fin("input.txt");
    fin >> r >> c;
    for (int i = 0; i < r; i++)
        for (int j = 0; j < c; j++)
            fin >> a[i][j];
    fin.close();
}

int Solve() {
    int ans = 0;
    for (int mask = 0; mask < (1 << (r * c)); mask++) {
        for (int i = 0; i < r; i++)
            for (int j = 0; j < c; j++)
                b[i][j] = (mask & (1 << (i * c + j))) > 0;
        bool ok = true;
        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) {
                int cnt = 0;
                for (int k = 0; k < 9; k++) {
                    int x = i + dx[k], y = j + dy[k];
                    if (x >= 0 && x < r && y >= 0 && y < c)
                        cnt += b[x][y];
                }
                if (cnt != a[i][j]) {
                    ok = false;
                    break;
                }
            }
            if (!ok) break;
        }
        if (ok) {
            int cnt = 0;
            for (int j = 0; j < c; j++)
                cnt += b[r / 2][j];
            ans = max(ans, cnt);
        }
    }
    return ans;
}

int main() {
    ofstream fout("output.txt");
    int nt;
    ifstream fin("input.txt");
    fin >> nt;
    for (int tt = 1; tt <= nt; tt++) {
        Load();
        fout << "Case #" << tt << ": " << Solve() << "\n";
    }
    fin.close();
    fout.close();
    return 0;
}
