struct dsu {
    std::vector<int> p;
    dsu(int n) : p(n) {
        for (int i = 0; i < n; i++)
            p[i] = i;
    }
    int get(int i) {
        return p[i] == i ? i : p[i] = get(p[i]);
    }
    void un(int i, int j) {
        p[get(i)] = get(j);
    }
};

inline int sqr(int x) {
    return x * x;
}

void solve(int test) {
    int n, x[1000], y[1000], z[1000], sx, sy, sz;
    ld S;
    scanf("%d%LF", &n, &S);
    for (int i = 0; i < n; i++)
        scanf("%d%d%d", &x[i], &y[i], &z[i]);
    scanf("%d%d%d", &sx, &sy, &sz);

    if (__multithreading) {
        if (__ids.size() == __limitofthreads) {
            int status, id = wait(&status);
            sprintf(__str, "output%d.txt", id);
            FILE* f = fopen(__str, "r");
            while (fgets(__str, 1000, f))
                printf("%s", __str);
            fclose(f);
            unlink(__str);
        }
        __id = fork();
        if (__id == 0) {
            FILE* f = fopen((__str + sprintf(__str, "output%d.txt", getpid())), "w");
            std::vector<ld> a;
            for (int i = 0; i < n; i++)
                for (int j = i + 1; j < n; j++)
                    a.push_back(sqrt(sqr(x[i] - x[j]) + sqr(y[i] - y[j]) + sqr(z[i] - z[j])));
            std::sort(ALL(a));
            dsu d(n);
            for (ld dist : a)
                for (int i = 0; i < n; i++)
                    for (int j = i + 1; j < n; j++)
                        if (d.get(i) != d.get(j) && dist * dist >= sqr(x[i] - x[j]) + sqr(y[i] - y[j]) + sqr(z[i] - z[j])) {
                            d.un(i, j);
                            if (d.get(0) == d.get(1)) {
                                fprintf(f, "%.16LF\n", (ld)dist);
                                fclose(f);
                                exit(0);
                            }
                        }
            fclose(f);
            exit(0);
        } else {
            __ids.push_back(__id);
        }
    } else {
        std::vector<ld> a;
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
                a.push_back(sqrt(sqr(x[i] - x[j]) + sqr(y[i] - y[j]) + sqr(z[i] - z[j])));
        std::sort(ALL(a));
        dsu d(n);
        for (ld dist : a)
            for (int i = 0; i < n; i++)
                for (int j = i + 1; j < n; j++)
                    if (d.get(i) != d.get(j) && dist * dist >= sqr(x[i] - x[j]) + sqr(y[i] - y[j]) + sqr(z[i] - z[j])) {
                        d.un(i, j);
                        if (d.get(0) == d.get(1)) {
                            printf("%.16LF\n", (ld)dist);
                            __inctests();
                            return;
                        }
                    }
    }
    __inctests();
}

