namespace {
    const double PI = 3.141592653589793;
    double x1, y1, x2, y2, x3, y3;
    double xx1, yy1, xx2, yy2, xx3, yy3;

    double square(double x1, double y1, double x2, double y2, double x3, double y3) {
        double a = x1 * (y2 - y3);
        double b = x2 * (y3 - y1);
        double c = x3 * (y1 - y2);
        return abs(a + b + c) / 2;
    }

    double len(double x, double y) {
        return sqrt(x * x + y * y);
    }

    void angle(double x1, double y1, double x2, double y2, double& c, double& s) {
        double dx1 = x1, dy1 = y1;
        double dx2 = x2, dy2 = y2;
        double xy = dx1 * dx2 + dy1 * dy2;
        double x1pm = dx1 * dx1 + dy1 * dy1;
        double x2pm = dx2 * dx2 + dy2 * dy2;
        c = xy / sqrt(x1pm * x2pm);
        s = (dx1 * dy2 - dy1 * dx2) / sqrt(x1pm * x2pm);
    }

    bool null(double v) {
        return abs(v) < 1E-9;
    }

    void solve() {
        cin >> x1 >> y1 >> x2 >> y2 >> x3 >> y3;
        cin >> xx1 >> yy1 >> xx2 >> yy2 >> xx3 >> yy3;
        double area1 = square(x1, y1, x2, y2, x3, y3);
        double area2 = square(xx1, yy1, xx2, yy2, xx3, yy3);
        if (null(area1) || null(area2) || (area1 * area2 < 0)) {
            cout << "No Solution" << endl;
            return;
        }
        double c, s, dx, dy, da;
        angle(x2 - x1, y2 - y1, xx2 - xx1, yy2 - yy1, c, s);
        dx = xx1 - x1;
        dy = yy1 - y1;
        da = atan2(s, c);
        double x = dx * cos(da) + dy * sin(da);
        double y = -dx * sin(da) + dy * cos(da);
        printf("%.9lf %.9lf %.9lf\n", x, y, da);
    }
}

