#define REP(i,n) for(int i=0;i<(n);i++)
#define FOR(i,k,n) for(int i=(k);i<=(n);i++)
#define FOREQ(i,k,n) for(int i=(k);i>=(n);i--)
#define FORIT(i,c) for(__typeof((c).begin()) i=(c).begin(); i!=(c).end(); i++)

#define SZ(v) ((int)v.size())
#define MEMSET(v,h) memset(v,h,sizeof(v))

int N;
V card;
vector<V> arr;

void printvi(V &vi)
{
    printf("(");
    for(int i=0; i<SZ(vi); i++)
    {
        if(i) printf(" ");
        printf("%d", vi[i]);
    }
    printf(")\n");
}

map<V, int> memo;
int cost(V &vi)
{
    if(memo.count(vi)) return memo[vi];
    int n = SZ(vi);
    int res = 0;
    FOR(i,1,n-1) res += abs(vi[i]-vi[i-1]);
    memo[vi] = res;
    return res;
}

void solve()
{
    scanf("%d", &N);
    card.clear();
    arr.clear();
    REP(i,N)
    {
        int x;
        scanf("%d", &x);
        card.push_back(x);
    }
    sort(card.begin(), card.end());
    do
    {
        arr.push_back(card);
    }
    while(next_permutation(card.begin(), card.end()));
    int best = -1;
    V ans;
    FORIT(it, arr)
    {
        int cur = cost(*it);
        if(best < cur)
        {
            best = cur;
            ans = *it;
        }
    }
    printvi(ans);
}

int main()
{
    int T;
    scanf("%d", &T);
    REP(t,T) solve();
    return 0;
}
