    tower(int x, int y, int r, int s) : x(x), y(y), r2(r * r), s(s) {}
};

int main(int argc, const char **argv) {
    redirect(argc, argv);
    int T;
    cin >> T;
    for (int t = 1; t <= T; t++) {
        int n;
        cin >> n;
        vector<tower> towers;
        for (int i = 0; i < n; i++) {
            int x, y, r, s;
            cin >> x >> y >> r >> s;
            towers.push_back(tower(x, y, r, s));
        }
        vector<vi> graph(n);
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int dx = towers[i].x - towers[j].x;
                int dy = towers[i].y - towers[j].y;
                int d2 = dx * dx + dy * dy;
                int r2 = towers[i].r2 + towers[j].r2;
