#include <bits/stdc++.h>
using namespace std;

const int N = 1e5 + 5;
#define REP(i,n) for(int i=0; i<(n); i++)

struct Edge {
    int v, cap, flow, back_ind;
    Edge *back;
};

int n, s, t, e[N], h[N];
vector<Edge> g[N];
vector<int> cur(N);

void bfs(int start, int start_h) {
    queue<int> q;
    memset(h, -1, sizeof h);
    h[start] = start_h;
    q.push(start);
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (Edge &ed : g[u]) {
            if (ed.cap - ed.flow > 0 && h[ed.v] == -1) {
                h[ed.v] = h[u] + 1;
                q.push(ed.v);
            }
        }
    }
}

void compute_flow() {
    memset(e, 0, sizeof e);
    bfs(s, 0);
    while (true) {
        bool pushed = false;
        REP(u, n) {
            if (e[u] > 0 && u != s && u != t) {
                for (int &i = cur[u]; i < (int)g[u].size(); i++) {
                    Edge &ed = g[u][i];
                    if (ed.cap - ed.flow > 0 && h[u] > h[ed.v]) {
                        int push = min(e[u], ed.cap - ed.flow);
                        ed.flow += push;
                        g[ed.v][ed.back_ind].flow -= push;
                        e[u] -= push;
                        e[ed.v] += push;
                        pushed = true;
                    }
                }
            }
        }
        if (!pushed) {
            int u;
            for (u = 0; u < n; u++) {
                if (e[u] > 0 && u != s && u != t) {
                    int min_h = INT_MAX;
                    for (Edge &ed : g[u]) {
                        if (ed.cap - ed.flow > 0) {
                            min_h = min(min_h, h[ed.v]);
                        }
                    }
                    if (min_h == INT_MAX) break;
                    h[u] = min_h + 1;
                }
            }
            if (u == n) break;
        }
    }
    int flow = 0;
    for (Edge &ed : g[s]) flow += ed.flow;
    cout << flow << "\n";
}

void add_edge(int a, int b, int c, int c_back = 0) {
    Edge ed1 = {b, c, 0, (int)g[b].size()};
    Edge ed2 = {a, c_back, 0, (int)g[a].size()};
    g[a].push_back(ed1);
    g[b].push_back(ed2);
    ed1.back = &g[b].back();
    ed2.back = &g[a].back();
}

int main() {
    int w, h, b;
    cin >> w >> h >> b;
    n = w * h + 2;
    s = 0, t = n - 1;
    REP(i, w) add_edge(s, i + 1, 1);
    REP(i, w) add_edge(i + 1 + (h - 1) * w, t, 1);
    REP(i, h - 2) REP(j, w) {
        add_edge(j + 1 + i * w, j + 1 + (i + 1) * w, 1);
    }
    REP(i, b) {
        int x1, y1, x2, y2;
        cin >> x1 >> y1 >> x2 >> y2;
        x1--, y1--;
        REP(i, x2 - x1 + 1) REP(j, y2 - y1 + 1) {
            add_edge(x1 + i + 1 + (y1 + j) * w, s, 0);
            add_edge(x1 + i + 1 + (y1 + j) * w, t, 0);
        }
    }
    compute_flow();
    return 0;
}
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll MOD = 1000000007;
const int Maxn = 100007;
ll jie[Maxn], dao[Maxn];

ll powMod(ll x, ll y) {
    ll res = 1;
    while (y) {
        if (y & 1) res = res * x % MOD;
        x = x * x % MOD;
        y >>= 1;
    }
    return res;
}

void getJie() {
    jie[0] = 1;
    for (int i = 1; i < Maxn; i++) jie[i] = jie[i - 1] * i % MOD;
    dao[Maxn - 1] = powMod(jie[Maxn - 1], MOD - 2);
    for (int i = Maxn - 2; i >= 0; i--) dao[i] = dao[i + 1] * (i + 1) % MOD;
}

ll c(ll x, int y) {
    return jie[x] * dao[y] % MOD * dao[x - y] % MOD;
}

int prim[Maxn], flag[Maxn];

void makePrim() {
    for (int i = 2; i < Maxn; i++) {
        if (!flag[i]) prim[++prim[0]] = i;
        for (int j = 1; j <= prim[0] && i * prim[j] < Maxn; j++) {
            flag[i * prim[j]] = 1;
            if (i % prim[j] == 0) break;
        }
    }
}

int sign(int x) {
    int cnt = 0;
    for (int i = 1; prim[i] * prim[i] <= x; i++) {
        if (x % prim[i] == 0) {
            int tmp = 0;
            while (x % prim[i] == 0) {
                tmp++;
                x /= prim[i];
            }
            if (tmp > 1) return 0;
            cnt++;
        }
    }
    if (x > 1) cnt++;
    return cnt % 2 ? -1 : 1;
}

int n, m;

int main() {
    makePrim();
    getJie();
    for (n = 1; n <= 100000; n++) {
        ll ret = 0;
        for (m = 1; m <= n; m++) {
            ret = (ret + c(n, m) * sign(m)) % MOD;
        }
        if (ret < 0) printf("%d\n", n);
    }
    return 0;
}
