long long gcd(long long a, long long b) {
    if (b == 0)
        return a;
    return gcd(b, a % b);
}

long long win(long long x, long long y) {
    if (x == y)
        return -1;
    if (y % x == 0 || x % y == 0)
        return 1;
    if (gcd(x, y) == abs(x - y))
        return -1;
    if (x > y && x < 2 * y || y > x && y < 2 * x)
        return -win(y, x);
    return 1;
}

