double make(point p, point q, double mid) {
    if (fabs(p.x - q.x) < zero)
        return p.y;
    return p.y + (q.y - p.y) * (mid - p.x) / (q.x - p.x);
}

bool check(double mid) {
    double area = 0.0;
    point prev, cur;
    for (int i = 0; i < n1; i++) {
        cur = point(l[i].x, make(l[i], l[(i + 1) % n1], mid));
        area += cur * (prev - cur);
        prev = cur;
    }
    for (int i = 0; i < n2; i++) {
        cur = point(r[i].x, make(r[i], r[(i + 1) % n2], mid));
        area += cur * (prev - cur);
        prev = cur;
    }
    return fabs(area) >= a - zero;
}

