    if (i == 0) {
        if (j == 0)
            return;
        res = max(res, p[j].norm());
        return;
    }
    if (cnt[j] > 0) {
        int cur = p[j] * pnt(dx, dy);
        cur = myAbs(cur);
        res = max(res, cur);
        --cnt[j];
        return;
    }
    if (j == 0) {
        ++used[i];
        was[used[i]] = i;
        cnt[used[i]] = 2;
        go(x, i - 1, used[i], dx, dy);
        --cnt[used[i]];
        --used[i];
        return;
    }
    if (used[i] == j)
        return;
    pnt diff = p[j] - p[used[i]];
    int cp = diff ^ pnt(dx, dy);
    if (sign(cp) == 0) {
        ++cnt[j];
        go(x, i, 0, dx, dy);
        --cnt[j];
    }
    if (sign(cp) > 0) {
        swap(dx, dy);
        dx = -dx;
    }
    ++cnt[j];
    go(x, i, j - 1, dx, dy);
    --cnt[j];
}

