bool can_do_it(int ratio, int req, int quantity) {
    int min_quantity = req * ratio * 0.9;
    int max_quantity = req * ratio * 1.1;
    return (quantity >= min_quantity && quantity <= max_quantity);
}

int solve(vector<int>& R, vector<vector<int>>& Q) {
    int N = Q.size();
    int P = Q[0].size();

    vector<vector<int>> sorted_Q(Q);
    for (int i = 0; i < N; i++) {
        sort(sorted_Q[i].begin(), sorted_Q[i].end());
    }

    vector<int> index(N, 0);
    int num_packages = 0;

    while (true) {
        int min_quantity = INT_MAX;
        for (int i = 0; i < N; i++) {
            if (index[i] < P) {
                min_quantity = min(min_quantity, sorted_Q[i][index[i]]);
            }
        }

        bool found = false;
        for (int ratio = 1; ratio <= 110; ratio++) {
            bool satisfy_all = true;
            for (int i = 0; i < N; i++) {
                if (index[i] < P && !can_do_it(ratio, R[i], sorted_Q[i][index[i]])) {
                    satisfy_all = false;
                    break;
                }
            }
            if (satisfy_all) {
                found = true;
                for (int i = 0; i < N; i++) {
                    if (index[i] < P) {
                        index[i]++;
                    }
                }
                num_packages++;
                break;
            }
        }

        if (!found) {
            bool all_done = true;
            for (int i = 0; i < N; i++) {
                if (index[i] < P) {
                    index[i]++;
                    all_done = false;
                    break;
                }
            }
            if (all_done) {
                break;
            }
        }
    }

    return num_packages;
}

