typedef pair<long long, long long> point;

bool cw(const point &a, const point &b, const point &c) {
    return (b.first - a.first) * (c.second - a.second) - (b.second - a.second) * (c.first - a.first) < 0;
}

vector<point> convexHull(vector<point> p) {
    int n = p.size();
    vector<point> hull;
    sort(p.begin(), p.end());
    for (int i = 0; i < n; i++) {
        while (hull.size() >= 2 && !cw(hull[hull.size() - 2], hull.back(), p[i])) hull.pop_back();
        hull.push_back(p[i]);
    }
    int k = hull.size();
    for (int i = n - 2; i >= 0; i--) {
        while (hull.size() > k && !cw(hull[hull.size() - 2], hull.back(), p[i])) hull.pop_back();
        hull.push_back(p[i]);
    }
    hull.pop_back();
    return hull;
}

bool on_line(point x, point a, point b) {
    return (x.first - a.first) * (b.second - a.second) == (x.second - a.second) * (b.first - a.first);
}

