nfa emp = nfa(1);
nfa ze = nfa(0);

nfa kl(nfa x) {
    nfa y = nfa(x.n + 1);
    fore(i, 0, x.n) fore(j, 0, x.n) fore(k, 0, 256) y.a[i][j + 1][k] = x.a[i][j][k];
    forn(i, x.n) y.a[i][x.n][0] = y.a[x.n][i][0] = 1;
    y.f = x.f;
    y.f.insert(y.n);
    return y;
}

nfa comb(nfa x, nfa y) {
    nfa z = nfa(x.n + y.n);
    fore(i, 0, x.n) fore(j, 0, x.n) fore(k, 0, 256) z.a[i][j][k] = x.a[i][j][k];
    fore(i, x.n, x.n + y.n) fore(j, x.n, x.n + y.n) fore(k, 0, 256) z.a[i][j][k] = y.a[i - x.n][j - x.n][k];
    forn(i, x.n) z.a[i][z.n - 1][0] = 1;
    forn(i, y.n) z.a[z.n - 1][i + x.n][0] = 1;
    z.f = x.f;
    for (int i : y.f) z.f.insert(i + x.n);
    return z;
}

nfa orr(vector<nfa> v) {
    nfa x = v[0];
    fore(i, 1, sz(v)) x = comb(x, v[i]);
    return x;
}

nfa str(string s) {
    nfa x = nfa(sz(s) + 1);
    fore(i, 0, sz(s)) x.a[i][i + 1][s[i]] = 1;
    x.f.insert(sz(s));
    return x;
}

nfa get(string &s, int &i) {
    if (s[i] == '(') {
        i++;
        nfa x = get(s, i);
        i++;
        return x;
    }
    if (s[i] == ')' || s[i] == '|') return ze;
    if (isalpha(s[i])) return str(string(1, s[i++]));
    if (s[i] == '*') {
        i++;
        return kl(get(s, i));
    }
    vector<nfa> v;
    while (s[i] != ')' && s[i] != '|') v.pb(get(s, i));
    nfa x = orr(v);
    if (s[i] == '|') {
        i++;
        x = comb(x, get(s, i));
    }
    return x;
}

set<int> bfs(nfa &x, int s) {
    queue<int> q;
    vb vis(x.n);
    set<int> ans;
    q.push(s);
    vis[s] = 1;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        if (x.f.count(u)) ans.insert(u);
        fore(v, 0, x.n) if (!vis[v] && x.a[u][v][0]) {
            vis[v] = 1;
            q.push(v);
        }
    }
    return ans;
}

set<int> get2(nfa &x, int s, char c) {
    set<int> ans;
    fore(i, 0, x.n) if (x.a[s][i][c]) ans.insert(i);
    return ans;
}

set<int> getnext(set<int> &s, nfa &x, char c) {
    set<int> ans;
    for (int u : s) {
        set<int> tmp = get2(x, u, c);
        ans.insert(all(tmp));
    }
    return ans;
}

ll F(int l, int r, nfa &x, set<int> &s) {
    if (l > r) return 0;
    if (l == r) return s.count(x.n - 1);
    int m = (l + r) / 2;
    ll ans = 0;
    set<int> tmp = s;
    fore(i, l, m + 1) {
        tmp = getnext(tmp, x, i);
        ans += F(i + 1, r, x, tmp);
    }
    return ans;
}

