#include <bits/stdc++.h>
using namespace std;

const int MAXN = 1e5 + 5;
const int MAXVN = MAXN + 2;
const int dist_inf = 1e9;
const int flow_inf = 1e9;

struct Arc {
    int to, revind, cap, flow;
    Arc(int _to, int _revind, int _cap, int _flow = 0) : to(_to), revind(_revind), cap(_cap), flow(_flow) {}
};

class DinicFlow {
private:
    int vn, src, sink;
    vector<vector<Arc>> adj;
    int dist[MAXVN], ql[MAXVN], qr[MAXVN], que[MAXVN];

    bool bfs_layer() {
        fill(dist, dist + vn, -1);
        dist[src] = 0;
        int l = 0, r = 0;
        que[r++] = src;
        for (l = 0; l < r; l++) {
            int u = que[l];
            for (Arc &arc : adj[u]) {
                int v = arc.to;
                if (dist[v] == -1 && arc.flow < arc.cap) {
                    dist[v] = dist[u] + 1;
                    que[r++] = v;
                }
            }
        }
        return dist[sink] != -1;
    }

    int dfs_push(int u, int pushed) {
        if (pushed == 0) return 0;
        if (u == sink) return pushed;
        for (int &iter = ql[u]; iter < (int)adj[u].size(); iter++) {
            Arc &arc = adj[u][iter];
            if (arc.cap > arc.flow && dist[u] + 1 == dist[arc.to]) {
                int pushed_back = dfs_push(arc.to, min(pushed, arc.cap - arc.flow));
                if (pushed_back) {
                    arc.flow += pushed_back;
                    adj[arc.to][arc.revind].flow -= pushed_back;
                    return pushed_back;
                }
            }
        }
        return 0;
    }

    int push_flow() {
        int pushed = 0;
        if (bfs_layer()) {
            fill(ql, ql + vn, 0);
            pushed += dfs_push(src, flow_inf);
        }
        return pushed;
    }

public:
    DinicFlow(int _vn, int _src, int _sink) : vn(_vn), src(_src), sink(_sink), adj(vn) {}

    void append(int u, int v, int cap) {
        adj[u].emplace_back(v, adj[v].size(), cap);
        adj[v].emplace_back(u, adj[u].size() - 1, 0);
    }

    int maxflow() {
        int flow = 0;
        while (int pushed = push_flow()) flow += pushed;
        return flow;
    }

    vector<int> mincut() {
        vector<int> vis(vn, 0);
        vis[src] = 1;
        queue<int> que;
        que.push(src);
        while (!que.empty()) {
            int u = que.front();
            que.pop();
            for (Arc &arc : adj[u]) {
                if (arc.cap > arc.flow && !vis[arc.to]) {
                    vis[arc.to] = 1;
                    que.push(arc.to);
                }
            }
        }
        vector<int> cut;
        for (int u = 0; u < vn; u++) {
            if (vis[u]) continue;
            for (Arc &arc : adj[u]) {
                if (vis[arc.to] && arc.cap > 0) cut.push_back(u);
            }
        }
        return cut;
    }

    vector<int> srccut() {
        vector<int> vis(vn, 0);
        vis[src] = 1;
        queue<int> que;
        que.push(src);
        while (!que.empty()) {
            int u = que.front();
            que.pop();
            for (Arc &arc : adj[u]) {
                if (arc.cap > arc.flow && !vis[arc.to]) {
                    vis[arc.to] = 1;
                    que.push(arc.to);
                }
            }
        }
        vector<int> cut;
        for (int u = 0; u < vn; u++) {
            if (vis[u]) cut.push_back(u);
        }
        return cut;
    }

    vector<int> sinkcut() {
        vector<bool> vis(vn, 0);
        queue<int> que;
        que.push(sink);
        vis[sink] = 1;
        while (!que.empty()) {
            int u = que.front();
            que.pop();
            for (Arc &arc : adj[u]) {
                int v = arc.to;
                if (arc.flow > 0 && !vis[v]) {
                    vis[v] = 1;
                    que.push(v);
                }
            }
        }
        vector<int> cut;
        for (int u = 0; u < vn; u++) {
            if (vis[u]) cut.push_back(u);
        }
        return cut;
    }

    bool mincut_is_isolated_sink() {
        vector<int> cut = mincut();
        for (int u : cut) {
            for (Arc &arc : adj[u]) {
                if (arc.to != src && arc.cap > 0) return false;
            }
        }
        return true;
    }
