                int nextTurns = emptyTurns + 1;
                if (nextTurns <= 100) {
                    res = max(res, solve(i, j, i, j, ate1 || i == v1, ate2 || j == v2, nextTurns));
                }
            }
        }
    }
    return memo[s1][s2][emptyTurns] = res;
}

void solve() {
    cin >> n;
    es.resize(n);
    ds.resize(n, vvi(n));
    forn(i, n) {
        forn(j, n) {
            int c;
            cin >> c;
            if (c != inf) es[i].pb(j);
        }
    }

    forn(k, n) forn(i, n) forn(j, n) {
        if (i == j) ds[i][j].pb(i);
        else if (es[i][k] && es[k][j]) {
            ds[i][j] = ds[i][k];
            ds[i][j].pb(k);
            ds[i][j].insert(ds[i][j].end(), ds[k][j].begin(), ds[k][j].end());
        }
    }

    int s1, s2, v1, v2;
    cin >> s1 >> v1 >> s2 >> v2;
    s1--, v1--, s2--, v2--;
    memo.assign(n, vvb(n, vb(101, false)));
    cout << solve(s1, s2, v1, v2, false, false, 0) << "\n";
}

bool endsWith(string a, string b) {
    if (b.size() > a.size()) return false;
    int n = a.size(), m = b.size();
    forn(i, n - m + 1) if (a.substr(i, m) == b) return true;
    return false;
}

