using namespace std;

const double eps = 1e-12;
double area;
double W;
int L, U;
int Lx[100005], Ly[100005], Ux[100005], Uy[100005];

int calc2(int* x, int* y, int i, double line) {
    double dx = x[i] - x[i - 1];
    double dy = y[i] - y[i - 1];
    if (fabs(dx) < eps) return y[i];
    return y[i - 1] + (line - x[i - 1]) * dy / dx;
}

double calc(int l, int u, double x) {
    if (x < Lx[0]) return Ly[0] - Uy[0];
    if (x > Lx[L]) return Ly[L] - Uy[U];
    return calc2(Lx, Ly, l, x) - calc2(Ux, Uy, u, x);
}

double solve(double now, double tar) {
    double lo = now, hi = W;
    while (hi - lo > eps) {
        double mid = (lo + hi) / 2;
        area += calc(lower_bound(Lx, Lx + L, mid) - Lx, upper_bound(Ux, Ux + U, mid) - Ux, mid) * (mid - now);
        if (area > tar) hi = mid;
        else lo = mid;
    }
    return lo;
}

int main() {
    ifstream fin("AL.in");
    ofstream fout("AL.out");
    int G;
    fin >> W >> L >> U >> G;
    for (int i = 0; i < L; i++) fin >> Lx[i] >> Ly[i];
    for (int i = 0; i < U; i++) fin >> Ux[i] >> Uy[i];
    double part = W * Ly[L] / G;
    double now = 0;
    fout << fixed;
    for (int i = 0; i < G; i++) {
        area = 0;
        now = solve(now, part * (i + 1));
        fout << setprecision(10) << now << endl;
    }
    fin.close();
    fout.close();
    return 0;
}
