const long long m = 1000000007;

void read() {
    scanf("%d%d", &n, &k);
}

void solve() {
    pps[0] = pp[0] = 1;
    for(int i = 1; i <= n; i++) {
        pps[i] = pps[i-1];
        pp[i] = pp[i-1];
        if(i >= k) {
            pps[i] = (pps[i] + pp[i-k]) % m;
            pp[i] = (pp[i] + pps[i-k]) % m;
        }
    }
    long long ans = 0;
    for(int i = 1; i <= n; i++)
        r[i] = (r[i-1] + pps[i]) % m;
    for(int i = k; i <= n; i++)
        ans = (ans + r[i] - r[i-k] + m) % m;
    printf("%lld\n", ans);
}

int main(int argc, char** argv) {
    int t = 1;
    if(argc > 1)
        t = atoi(argv[1]);
    REP(i,t) {
        if(argc > 2 && i+1 < atoi(argv[2]))
            continue;
        read();
        solve();
    }
    return 0;
}
