bool between(const pt& a, const pt& b, const pt& c) {
    int vx = b.X - a.X, vy = b.Y - a.Y, wx = c.X - a.X, wy = c.Y - a.Y;
    if (vx * wx + vy * wy < 0) return false;
    if (vx * wx + vy * wy == 0) return abs(wx) <= abs(vx) && abs(wy) <= abs(vy);
    int q = vx * wx + vy * wy;
    int r = vx * vx + vy * vy;
    return 0 <= q && q <= r;
}

inline int dist2(int ax, int ay, int bx, int by) {
    return sqr(ax - bx) + sqr(ay - by);
}

inline bool check(int px, int py) {
    return correct(px, py, h, w) && f[px][py] == '.' && dist2(px, py, sx, sy) <= d * d;
}

int solve() {
    int ans = 0;
    forn(sx, h) forn(sy, w) if (check(sx, sy)) {
        was = vector<pt>(1, mp(sx, sy));
        forn(i, h) forn(j, w) if (check(i, j)) {
            bool ok = true;
            forn(k, sz(was)) if (between(was[k], mp(i, j), mp(sx, sy))) { ok = false; break; }
            if (ok) was.pb(mp(i, j));
        }
        ans = max(ans, sz(was));
    }
    return ans;
}

