ll a[37], n, b;

ll profit(ll mn, ll k) {
    ll s1 = 0, s2 = 0;
    REP(i, k) {
        if (a[i] > mn) return 0;
        s1 += mn - a[i];
    }
    FOR(i, k, n - 1) {
        s2 += max(0ll, mn + 1 - a[i]);
    }
    if (s1 + s2 > b) return 0;
    return s1 * 36.0 / k - s1 - s2;
}

bool can(ll mn, ll k) {
    ll s = 0;
    REP(i, k) s += max(0ll, mn - a[i]);
    FOR(i, k, n - 1) s += max(0ll, mn + 1 - a[i]);
    return s <= b;
}

ll find_mx(int k) {
    ll lo = 0, hi = 1e15, ans = 0;
    while (lo <= hi) {
        ll mid = (lo + hi) / 2;
        if (can(mid, k))
            ans = mid, lo = mid + 1;
        else
            hi = mid - 1;
    }
    return ans;
}

int main() {
    int T;
    cin >> T;
    while (T--) {
        cin >> b >> n;
        REP(i, n) cin >> a[i];
        sort(a, a + n);
        double mx = 0;
        FOR(k, 1, 36) {
            ll mn = find_mx(k);
            if (mn > 0) {
                vll v;
                v.pb(mn - 2);
                v.pb(mn - 1);
                v.pb(mn);
                v.pb(mn + 1);
                v.pb(mn + 2);
                for (auto x : v) mx = max(mx, profit(x, k));
            }
        }
        cout << fixed << setprecision(10) << mx << "\n";
    }
    return 0;
}
