int findb(int r, int c, MOVE prevm, vector<string> &matr)
{
    if (r >= R || c >= C || matr[r][c] == '#')
        return -1;
    if (r == R - 1 && c == C - 1)
        return 0;
    int res = 1e9;
    if (prevm != DR)
        res = min(res, findb(r, c + 1, RT, matr) + 1);
    if (prevm != DL)
        res = min(res, findb(r + 1, c, DR, matr) + 1);
    if (prevm != RT)
        res = min(res, findb(r, c - 1, LT, matr) + 1);
    if (prevm != LT)
        res = min(res, findb(r - 1, c, DL, matr) + 1);
    if (res == 1e9)
        return -1;
    if (res <= F)
        return res;
    return -1;
}

