typedef vector<VI> VVI;
typedef pair<int, int> PII;
typedef vector<PII> VPII;

const int INF = 1e9;

VI primes;
bool isPrime[1025];

class DisjointSet {
private:
    VI parent, rank;

public:
    DisjointSet(int N) {
        rank.assign(N, 0);
        parent.resize(N);
        F0R(i, N) parent[i] = i;
    }

    int findRoot(int v) {
        if (parent[v] == v)
            return v;
        return parent[v] = findRoot(parent[v]);
    }

    void unite(int u, int v) {
        u = findRoot(u);
        v = findRoot(v);
        if (rank[u] < rank[v])
            swap(u, v);
        parent[v] = u;
        if (rank[u] == rank[v])
            rank[u]++;
    }

    int getNumSets() {
        int count = 0;
        F0R(i, sz(parent))
            if (parent[i] == i)
                count++;
        return count;
    }
};

bool isPrime(int P) {
    if (P < 2)
        return false;
    if (P < 1025)
        return isPrime[P];
    for (int p : primes) {
        if (P % p == 0)
            return false;
        if (p * p > P)
            break;
    }
    return true;
}

int solve(int A, int B, int P) {
    DisjointSet ds(B - A + 1);
    for (int p = P; p * p <= B; p++) {
        if (!isPrime(p))
            continue;
        for (int x = max(A, p * p); x <= B; x += p)
            if (x - A >= 0)
                ds.unite(x - A, (x - A) / p);
    }
    return ds.getNumSets();
}

int main() {
    isPrime[2] = true;
    FOR(i, 3, 1025) {
        bool prime = true;
        for (int j = 2; j * j <= i; j++)
            if (i % j == 0) {
                prime = false;
                break;
            }
        isPrime[i] = prime;
        if (prime)
            primes.pb(i);
    }

    ifstream fin("B-large.in");
    ofstream fout("B-large.out");
    int T;
    fin >> T;
    F0R(t, T) {
        int A, B, P;
        fin >> A >> B >> P;
        fout << "Case #" << t + 1 << ": " << solve(A, B, P) << endl;
    }
    fin.close();
    fout.close();
    return 0;
}
