        for (int i = 0; i < S; i++) {
            if (s[i] == in) {
                if (mark[i] == false) {
                    mark[i] = true;
                    x++;
                    if (x == S) {
                        for (int j = 0; j < S; j++)
                            mark[j] = false;
                        return true;
                    }
                }
                return false;
            }
        }
        return false;
    }

    void reset(int p) {
        for (int i = 0; i < S; i++)
            mark[i] = false;
        mark[p] = true;
        x = 1;
    }
};

