        double dot = dx1 * dx2 + dy1 * dy2;
        double th = gogo(dot / (dis(x[i], y[i], xx, yy) * dis(x[j], y[j], xx, yy)));
        area += cross * acos(th) / (2 * PI);
    }
    return fabs(area);
}

