int fun_pt(int x) {
    x += max_pt;
    int m = x & -x , c = 0;
    while(x>0) {
        x -= m;
        m >>= 1;
        c++;
    }
    return c;
}

void update_pt(int x, int vl) {
    x += max_pt;
    POW_TREE[x] = vl;
    for(int i = fun_pt(x); i > 0; i--) {
        int y = x - (1<<(i-1));
        POW_TREE[y] = min(POW_TREE[y<<1],POW_TREE[(y<<1)|1]);
    }
}

int pref_pt(int x) {
    x += max_pt;
    int res = inf;
    for(int i = fun_pt(x); i > 0; i--) {
        res = min(res,POW_TREE[x-(1<<(i-1))]);
    }
    return res;
}

