#define MOD 1000000007ll
#define MAX 1000010

ll F[MAX], Finv[MAX], inv[MAX];
ll dp0[MAX], dp1[MAX];

ll comb(int N, int K) {
    return (F[N] * Finv[K] % MOD * Finv[N - K] % MOD);
}

void pre(void) {
    F[0] = 1;
    for (int i = 1; i < MAX; i++)
        F[i] = (F[i - 1] * i) % MOD;
    Finv[MAX - 1] = pow(F[MAX - 1], MOD - 2, MOD);
    for (int i = MAX - 2; i >= 0; i--)
        Finv[i] = (Finv[i + 1] * (i + 1)) % MOD;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++)
        inv[i] = (MOD - (MOD / i) * inv[MOD % i] % MOD) % MOD;
    dp0[0] = 1;
    for (int i = 1; i < MAX; i++) {
        dp0[i] = dp0[i - 1];
        for (int j = 1; j <= i; j++)
            dp0[i] = (dp0[i] + comb(i, j) * dp1[i - j]) % MOD;
    }
    dp1[0] = 0;
    for (int i = 1; i < MAX; i++) {
        dp1[i] = dp1[i - 1];
        for (int j = 1; j <= i; j++)
            dp1[i] = (dp1[i] + comb(i, j) * dp0[i - j]) % MOD;
    }
}

