    while (t--) {
        int n;
        cin >> n;
        vector<double> x(n), y(n), z(n);
        for (int i = 0; i < n; i++) {
            cin >> x[i] >> y[i] >> z[i];
        }
        bool ok = true;
        for (int i = 0; i < n; i++) {
            double bx, by, bz, tx, ty, tz;
            if (x[i] == 0 && y[i] == 0) {
                bx = 1;
                by = 0;
                bz = 0;
            } else {
                bx = -y[i];
                by = x[i];
                bz = 0;
            }
            double norm = sqrt(bx * bx + by * by + bz * bz);
            bx /= norm;
            by /= norm;
            bz /= norm;
            tx = by * bz - bx * 0;
            ty = bx * 0 - bx * bz;
            tz = bx * by - by * bx;
            norm = sqrt(tx * tx + ty * ty + tz * tz);
            tx /= norm;
            ty /= norm;
            tz /= norm;
            bool skip = false;
            for (int j = 0; j < n; j++) {
                if (i != j && x[i] == -x[j] && y[i] == -y[j] && z[i] == -z[j]) {
                    skip = true;
                    break;
                }
            }
            if (skip) continue;
            vector<double> angles;
            for (int j = 0; j < n; j++) {
                if (i != j) {
                    double dx = x[j] - x[i];
                    double dy = y[j] - y[i];
                    double dz = z[j] - z[i];
                    double dot = bx * dx + by * dy + bz * dz;
                    angles.push_back(acos(dot));
                }
            }
            sort(angles.begin(), angles.end());
            double prev = angles[0];
            for (int j = 1; j < angles.size(); j++) {
                double cur = angles[j];
                if (cur - prev > pi + eps) {
                    ok = false;
                    break;
                }
                prev = cur;
            }
            if (!ok) break;
        }
        cout << (ok ? "YES" : "NO") << endl;
    }
    return 0;
}
