int dfsinv(int u, int proib) {
    int ret = 1;
    empilhado[u] = 1;
    for (int i = 0; i < nadjinv[u]; i++) {
        int v = adjinv[u][i];
        if (v != proib && !empilhado[v]) {
            ret = max(ret, 1 + dfsinv(v, proib));
        }
    }
    empilhado[u] = 0;
    return ret;
}

void SCC(int u) {
    indx[u] = lowlink[u] = I++;
    S[Stop++] = u;
    empilhado[u] = 1;
    for (int i = 0; i < nadj[u]; i++) {
        int v = adj[u][i];
        if (indx[v] == -1) {
