bool bad(int x, int y) {
    if (x < 0 || y < 0 || x >= N || y >= N)
        return true;
    if (flag(x, y) || flag(x + 1, y) || flag(x, y + 1) || flag(x + 1, y + 1))
        return true;
    return false;
}

bool bfsT(int sx, int sy, int tx, int ty, bool bf, int cx, int cy) {
    memset(dT, -1, sizeof dT);
    memset(usedT, 0, sizeof usedT);
    timerT = 0;
    dT[sx * N + sy] = 0;
    usedT[sx * N + sy] = 1;
    int qh = 0, qt = 0;
    qu[qt++] = sx * N + sy;
    while (qh < qt) {
        int cur = qu[qh++];
        int x = cur / N, y = cur % N;
        if (x == tx && y == ty)
            return true;
        if (bf && x == cx && y == cy)
            f[cx][cy] = '.';
        for (int d = 0; d < 4; d++) {
            int nx = x + DX[d], ny = y + DY[d];
            if (nx >= 0 && nx < N && ny >= 0 && ny < N && !flag(nx, ny) && !bad(nx, ny) && dT[nx * N + ny] == -1) {
                dT[nx * N + ny] = dT[cur] + 1;
                usedT[nx * N + ny] = 1;
                qu[qt++] = nx * N + ny;
            }
        }
    }
    return false;
}

