        if (bf && x == cx && y == cy)
            f[cx][cy] = '.';
        for (int d = 0; d < 4; d++) {
            int nx = x + DX[d], ny = y + DY[d];
            if (nx >= 0 && nx < N && ny >= 0 && ny < N && !flag(nx, ny) && !bad(nx, ny) && d[nx * N + ny] == -1) {
                d[nx * N + ny] = d[cur] + 1;
                used[nx * N + ny] = 1;
                qu[qt++] = nx * N + ny;
            }
        }
    }
    return false;
}

