int BFS(int BFF[], int seen[], int N, int source, int start, int previous) {
    seen[source] = 1;
    int length = 1;
    int next = BFF[source];
    if (next == start) {
        return 2;
    }
    if (seen[next] || next == previous) {
        return 1;
    }
    length += BFS(BFF, seen, N, next, start, source);
    return length;
}

