ll gaub(vector<vector<ll>> a, int n) {
    ll res = 1, x;
    for (int i = 0; i < n; i++) {
        int k = i;
        for (int j = i + 1; j < n; j++)
            if (abs(a[j][i]) > abs(a[k][i])) k = j;
        if (!a[k][i]) return 0;
        if (k != i) {
            res = -res;
            swap(a[i], a[k]);
        }
        x = a[i][i];
        res *= x;
        for (int j = 0; j < n; j++) {
            if (j != i && a[j][i]) {
                ll z = a[j][i];
                for (int k = i; k < n; k++) a[j][k] -= z * a[i][k] / x;
            }
        }
    }
    return res;
}

