using namespace std;

const double eps = 1e-9;
const int Len = 10;
const double Inf = 1e9;

struct Node {
    int l, v;
    double x;
};

int n, inf;
double ans;
char s[100];

void sol(vector<Node> a, double st, int id) {
    int l, r, ln, rn;
    l = r = -1;
    double mind = Inf, d;
    for (int i = 0; i < n; i++) {
        if (i == id) continue;
        if (a[i].l != a[id].l) {
            d = fabs(a[i].x - a[id].x + (a[id].v - a[i].v) * st);
            if (d < Len) {
                inf = 1;
                return;
            }
            if (d < mind) {
                mind = d;
                ln = i;
                rn = id;
                if (a[i].l) swap(ln, rn);
            }
        }
    }
    if (mind == Inf) {
        ans = max(ans, st);
        return;
    }
    double tm = mind - Len;
    tm /= a[rn].v + a[ln].v;
    a[rn].x += a[rn].v * tm;
    a[ln].x -= a[ln].v * tm;
    sol(a, st + tm, rn);
    sol(a, st + tm, ln);
}

