void Go(int Dep) {
    if (Opt == INF)
        return;
    if (Dep > Opt)
        Opt = Dep;
    if (a[my][mx] == 0)
        return;
    bool ok = false;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
            if (a[i][j] && (i != my || j != mx)) {
                ok = true;
                break;
            }
    if (!ok) {
        Opt = INF;
        return;
    }
    int backup[5][5];
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
            backup[i][j] = a[i][j];
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
            if (a[i][j] && (i != my || j != mx)) {
                int mx = 0;
                for (int k = 0; k < 4; k++) {
                    int x = i + dx[k], y = j + dy[k];
                    if (x >= 0 && x < n && y >= 0 && y < m)
                        mx = max(mx, a[x][y]);
                }
                c[i][j] = mx;
            }
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
            a[i][j] -= c[i][j], a[i][j] = max(a[i][j], 0);
    Go(Dep + 1);
    for (int k = 0; k < 4; k++) {
        int x = my + dx[k], y = mx + dy[k];
        if (x >= 0 && x < n && y >= 0 && y < m && a[x][y]) {
            swap(a[my][mx], a[x][y]);
            mx = x, my = y;
            Go(Dep + 1);
            swap(a[my][mx], a[x][y]);
            mx = x, my = y;
        }
    }
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
            a[i][j] = backup[i][j];
}

