const double eps = 1e-9;

void check(double A, double B, double C) {
    double medx = 0, medy = 0;
    for (int i = 0; i < n; i++) {
        medx += x[i];
        medy += y[i];
    }
    medx /= n;
    medy /= n;
    if (fabs(A * medx + B * medy + C) > eps) return;

    vector < double > d1, d2;
    for (int i = 0; i < n; i++) {
        double dx = x[i] - medx;
        double dy = y[i] - medy;
        d1.push_back(A * dx + B * dy);
        d2.push_back(B * dx - A * dy);
    }
    sort(d1.begin(), d1.end());
    sort(d2.begin(), d2.end());
    double mind1 = d1[0], maxd1 = d1[0], mind2 = d2[0], maxd2 = d2[0];
    for (int i = 1; i < n; i++) {
        mind1 = min(mind1, d1[i]);
        maxd1 = max(maxd1, d1[i]);
        mind2 = min(mind2, d2[i]);
        maxd2 = max(maxd2, d2[i]);
    }
    if (fabs(mind1) > eps || fabs(maxd1) > eps || fabs(mind2) > eps || fabs(maxd2) > eps) return;
    res.push_back(make_pair(medx - B / A, medy + 1 / A));
    res.push_back(make_pair(medx + B / A, medy - 1 / A));
}

void solve(double A, double B, double C) {
    check(A, B, C);
    check(A + eps, B, C);
    check(A - eps, B, C);
    check(A, B + eps, C);
    check(A, B - eps, C);
    check(A, B, C + eps);
    check(A, B, C - eps);
}

