void readData(std::fstream& in, int& numTests, std::queue<std::pair<int, std::pair<int, int>>>& testData) {
    in >> numTests;
    for (int i = 0; i < numTests; i++) {
        int cells, rows, cols;
        in >> cells >> rows >> cols;
        testData.push(std::make_pair(cells, std::make_pair(rows, cols)));
    }
}

void solveAndWrite(std::fstream& out, int numTests, std::queue<std::pair<int, std::pair<int, int>>>& testData) {
    for (int i = 1; i <= numTests; i++) {
        int cells = testData.front().first;
        int rows = testData.front().second.first;
        int cols = testData.front().second.second;
        testData.pop();

        bool richardWins = (cells % (rows * cols) != 0) || (cells >= 7) || (cells > rows && cells > cols) || (std::ceil(cells / 2.0) > std::min(rows, cols));
        bool gabrielWins = (cells == 1) || (cells == 2) || (cells == 3);
        if (cells == 4 && std::min(rows, cols) > 2) {
            gabrielWins = true;
        } else if (cells == 5 && std::min(rows, cols) == 3 && std::max(rows, cols) == 5) {
            richardWins = true;
        } else if (cells == 6 && std::min(rows, cols) > 3) {
            gabrielWins = true;
        }

        out << "Case #" << i << ": " << (richardWins ? "RICHARD" : (gabrielWins ? "GABRIEL" : "RICHARD")) << std::endl;
    }
}

