ull MOD = 1000000007;
ull n, b;
ull digits[64];
ull size;
ull memo[64][64][64][64];

ull calc(ull depth, ull prev, ull up, ull bottom) {
    if(depth == size) return up == bottom;
    ull& res = memo[depth][prev][up][bottom];
    if(res != -1) return res;
    res = 0;
    for(ull d = 0; d < b; ++d) {
        ull new_up = up + digits[depth];
        ull new_bottom = (bottom + d) % b;
        res += calc(depth + 1, d, new_up, new_bottom);
        res %= MOD;
    }
    return res;
}

int main() {
    ull test;
    scanf("%llu", &test);
    while(test--) {
        scanf("%llu%llu", &n, &b);
        size = 0;
        MEMSET(memo, -1);
        while(n) {
            digits[size++] = n % b;
            n /= b;
        }
        reverse(digits, digits + size);
        printf("%llu\n", calc(0, -1, 0, 0));
    }
    return 0;
}
