bool report(int q) {
    ans.insert(q);
    if (ans.size() > 2) bun = true;
    return bun;
}

void work(int m, int b[], int r) {
    if (m <= 1) {
        bun = true;
        return;
    }
    for (int i = 0; i < m; i++) {
        if (report(b[i])) return;
        int v = (r - b[i] + mm) % mm;
        for (int j = i + 1; j < m; j++) {
            if (b[j] == v) {
                int c[1010];
                for (int k = 0; k < i; k++) c[k] = b[k];
                for (int k = i; k < j; k++) c[k] = 0;
                for (int k = j + 1; k < m; k++) c[k - (j - i)] = b[k];
                work(m - (j - i), c, v);
            }
        }
    }
}

