using LD = long double;
const LD kEps = 1E-9;
const int MaxSiz = 1e6 + 5;
vector<int> divisors[MaxSiz];
int nxtPrime[MaxSiz];
int moebius[MaxSiz];
vector<int> factor(int x) {
    vector<int> ret;
    for (int i = 2; i * i <= x; i++) {
        if (x % i == 0) {
            ret.PB(i);
            while (x % i == 0) x /= i;
        }
    }
    if (x > 1) ret.PB(x);
    return ret;
}
void preproc() {
    divisors[1].PB(1);
    for (int i = 2; i < MaxSiz; i++) {
        if (nxtPrime[i] == 0) {
            nxtPrime[i] = i;
            moebius[i] = -1;
            divisors[i].PB(1);
            divisors[i].PB(i);
        }
        for (int j = i + i; j < MaxSiz; j += i)
            nxtPrime[j] = i;
        for (int j = i + i; j < MaxSiz; j += i) {
            int k = j;
            divisors[j].PB(i);
            while (k % i == 0) {
                if (k / i % i == 0) {
                    moebius[j] = 0;
                    break;
                } else
                    k /= i;
            }
        }
    }
}
struct Test {
    int N, R;
    set<pair<LD, LD>> taken;
    void run(int testid) {
        cin >> N >> R;
        int res = 0;
        for (auto d : divisors[N]) {
            int m = N / d;
            if (moebius[m]) res += moebius[m] * (R / d) * (R / d);
        }
        for (auto pp : taken) {
            LD x = pp.FI, y = pp.SE;
            LD d = sqrt(x * x + y * y);
            if (d <= R + kEps) res--;
        }
        for (auto p : factor(N)) {
            LD x = (R * (p - 2 * (N / p)));
            LD y = (R * (p - 2 * (N / p) % p));
            taken.insert({x, y});
        }
        cout << "Case #" << testid << ": " << res << "\n";
    }
};

