}

bool can(string ss, int r, int p, int s) {
    for (char c : ss) {
        if (c == 'R') r--;
        else if (c == 'P') p--;
        else s--;
        if (r < 0 || p < 0 || s < 0) return false;
    }
    return true;
}

string sort_f(string s, int n) {
    if (n == 0 || s.length() <= 1) return s;
    int mid = s.length() / 2;
    string l = sort_f(s.substr(0, mid), n - 1);
    string r = sort_f(s.substr(mid, s.length() - mid), n - 1);
    string res = "";
    while (!l.empty() && !r.empty()) {
        if (l < r) {
            res += l[0];
            l = l.substr(1);
        } else {
            res += r[0];
            r = r.substr(1);
        }
    }
    res += l + r;
    return res;
}

