template<typename T>
vector<pair<T, int>> factorize(T n) {
    vector<pair<T, int>> res;
    for (T i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            int cnt = 0;
            while (n % i == 0) {
                cnt++;
                n /= i;
            }
            res.push_back(make_pair(i, cnt));
        }
    }
    if (n > 1) res.push_back(make_pair(n, 1));
    return res;
}

template<typename T>
bool isPrimeNumber(T n) {
    if (n <= 1) return false;
    if (n <= 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;
    for (T i = 5; i * i <= n; i += 6)
        if (n % i == 0 || n % (i + 2) == 0)
            return false;
    return true;
}

template<typename T>
T eularFunction(T n) {
    T res = n;
    for (T i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            while (n % i == 0) n /= i;
            res -= res / i;
        }
    }
    if (n > 1) res -= res / n;
    return res;
}

