bool bfs(vector<set<int>>& graph, int vertex = 0, ostream& stream = cout) {
    if (vertex < 0 || vertex >= graph.size())
        return false;

    vector<bool> visited(graph.size(), false);
    queue<int> q;
    q.push(vertex);
    visited[vertex] = true;

    while (!q.empty()) {
        int v = q.front();
        q.pop();

        for (int it : graph[v]) {
            if (!visited[it]) {
                visited[it] = true;
                q.push(it);
            } else if (it != vertex) {
                return true;
            }
        }
    }

    return false;
}

