char buf[1000005], buf2[1000005];

void swap(int i, int j) {
    char temp = buf[i];
    buf[i] = buf[j];
    buf[j] = temp;
}

int asdf(const void *a, const void *b) {
    return *(char *)b - *(char *)a;
}

void aa() {
    int n = strlen(buf);
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            if (buf[j] > buf[j + 1]) {
                swap(j, j + 1);
            }
        }
    }

    bool allSame = true;
    for (int i = 1; i < n; i++) {
        if (buf[i] != buf[0]) {
            allSame = false;
            break;
        }
    }

    if (allSame) {
        int lastNonZero = n - 1;
        while (buf[lastNonZero] == '0') {
            lastNonZero--;
        }
        swap(lastNonZero, n - 1);
        std::qsort(buf, n, sizeof(char), asdf);
    } else {
        int rightmostSmallest = n - 2;
        while (rightmostSmallest >= 0 && buf[rightmostSmallest] == buf[n - 1]) {
            rightmostSmallest--;
        }
        swap(rightmostSmallest + 1, n - 1);
        std::qsort(buf, n, sizeof(char), asdf);
    }
}

