double most_like(int q) {
    if (q == Q) return 1.0;

    if (conta[q]) return table[q][0];

    double& ans = table[q][conta[q]++];
    ans = 0.0;

    for (int i = 0; i < 4; i++) {
        double p = odds[q][i];
        if (p > 0.0) {
            ans += p * most_like(q+1);
        }
    }

    return ans;
}

