struct card {
    int c, s, t;
    bool flag;
};

int T, N, M;
card a[100], b[100], c[100];

int checkMax(int c0, int c1, int c2) {
    int score = 0;
    for (int i = 0; i < N; i++) {
        if (a[i].flag && a[i].c == 0 && c0) {
            score += a[i].s;
            c0--;
            for (int j = 0; j < a[i].t; j++) {
                if (c1) {
                    c1--;
                } else if (c2) {
                    c2--;
                } else {
                    return score;
                }
            }
        }
    }
    for (int i = 0; i < N; i++) {
        if (a[i].flag && a[i].c == 1 && c1) {
            score += a[i].s;
            c1--;
            for (int j = 0; j < a[i].t; j++) {
                if (c2) {
                    c2--;
                } else {
                    return score;
                }
            }
        }
    }
    for (int i = 0; i < N; i++) {
        if (a[i].flag && a[i].c == 2 && c2) {
            score += a[i].s;
            c2--;
        }
    }
    for (int i = 0; i < M; i++) {
        if (b[i].flag && b[i].c == 0 && c0) {
            score += b[i].s;
            c0--;
            for (int j = 0; j < b[i].t; j++) {
                if (c1) {
                    c1--;
                } else if (c2) {
                    c2--;
                } else {
                    return score;
                }
            }
        }
    }
    for (int i = 0; i < M; i++) {
        if (b[i].flag && b[i].c == 1 && c1) {
            score += b[i].s;
            c1--;
            for (int j = 0; j < b[i].t; j++) {
                if (c2) {
                    c2--;
                } else {
                    return score;
                }
            }
        }
    }
    for (int i = 0; i < M; i++) {
        if (b[i].flag && b[i].c == 2 && c2) {
            score += b[i].s;
            c2--;
        }
    }
    return score;
}

bool checkPossible(int c0, int c1, int c2) {
    int totalCards = c0 + c1 + c2;
    if (totalCards == 0) {
        return true;
    }
    if (c0 == 0) {
        return (c1 >= c2);
    }
    if (c1 == 0) {
        return false;
    }
    if (c2 == 0) {
        return true;
    }
    return true;
}

int solve() {
    int maxScore = 0;
    for (int c0 = 0; c0 <= N; c0++) {
        for (int c1 = 0; c1 <= N - c0; c1++) {
            int c2 = N - c0 - c1;
            if (checkPossible(c0, c1, c2)) {
                int tempScore = checkMax(c0, c1, c2);
                maxScore = max(maxScore, tempScore);
            }
        }
    }
    return maxScore;
}

int main() {
    freopen("C-large.in", "r", stdin);
    freopen("out.txt", "w", stdout);
    scanf("%d", &T);
    for (int t = 1; t <= T; t++) {
        scanf("%d %d", &N, &M);
        for (int i = 0; i < N; i++) {
            scanf("%d %d %d", &a[i].c, &a[i].s, &a[i].t);
            a[i].flag = true;
        }
        for (int i = 0; i < M; i++) {
            scanf("%d %d %d", &b[i].c, &b[i].s, &b[i].t);
            b[i].flag = true;
        }
        int maxScore = solve();
        printf("Case #%d: %d\n", t, maxScore);
    }
    return 0;
}
