int tst, r, c;
char in[20][20];
int dp[1 << 16][5][5];

int go(int mask, int cr, int cc) {
    if (dp[mask][cr][cc] != -1)
        return dp[mask][cr][cc];

    int &ret = dp[mask][cr][cc];
    ret = 0;

    REP(dr, 5) REP(dc, 5) {
        int nr = cr + dr - 2, nc = cc + dc - 2;
        if (nr >= 0 && nr < r && nc >= 0 && nc < c && in[nr][nc] == 'R') {
            int nmask = mask | (1 << (nr * c + nc));
            if (go(nmask, nr, nc)) {
                ret = 1;
            }
        }
    }

    return ret;
}

