using namespace std;

struct Point {
    int x, y;
} p[1005];

int n, res, color[1005], dl[1005], dr[1005], ch[1005], c;

bool cmp(Point a, Point b) {
    if (a.y == b.y) return a.x < b.x;
    return a.y < b.y;
}

int lowbit(int x) {
    return x & (-x);
}

bool dfs(int u) {
    if (c > res) return false;
    if (u > n) return true;
    bool ok = false;
    for (int i = 0; i < res; i++) {
        if (ch[i] == 0) continue;
        if (dl[u] && color[dl[u]] == i) continue;
        if (dr[u] && color[dr[u]] == i) continue;
        color[u] = i;
        ch[i] -= lowbit(ch[i]);
        c++;
        if (dfs(u + 1)) {
            ok = true;
            break;
        }
        ch[i] += lowbit(ch[i]);
        c--;
    }
    if (!ok) {
        color[u] = res;
        ch[res] = 1 << res;
        c++;
        ok = dfs(u + 1);
        c--;
        ch[res] = 0;
    }
    return ok;
}

int main() {
    int T;
    cin >> T;
    while (T--) {
        cin >> n;
        for (int i = 1; i <= n; i++) cin >> p[i].x >> p[i].y;
        sort(p + 1, p + n + 1, cmp);
        for (int i = 1; i <= n; i++) {
            dl[i] = dr[i] = 0;
            for (int j = i - 1; j >= 1; j--) {
                if (p[j].y < p[i].y) {
                    dl[i] = j;
                    break;
                }
            }
            for (int j = i - 1; j >= 1; j--) {
                if (p[j].y < p[i].y && p[j].x > p[i].x) {
                    dr[i] = j;
                    break;
                }
            }
        }
        color[1] = 0;
        res = 1;
        memset(ch, 0, sizeof(ch));
        ch[0] = 1;
        c = 1;
        while (true) {
            if (dfs(2)) break;
            res++;
            if (res > 4) break;
        }
        cout << res << endl;
    }
    return 0;
}
