const double eps = 1e-9;

int main() {
    int number_of_tests;
    std::cin >> number_of_tests;

    for (int test_number = 1; test_number <= number_of_tests; ++test_number) {
        int n, k, u;
        std::cin >> n >> k >> u;

        std::vector<double> probs(n);
        double total_sum = 0.0, total_product = 1.0;
        for (int i = 0; i < n; ++i) {
            std::cin >> probs[i];
            total_sum += probs[i];
            total_product *= probs[i];
        }

        std::sort(probs.rbegin(), probs.rend());

        double best = 0.0;
        double current_sum = 0.0;
        double current_product = 1.0;
        for (int i = 0; i < n; ++i) {
            current_sum += probs[i];
            current_product *= probs[i];
            if (current_sum > u + eps) {
                break;
            }
            if (i < k) {
                best = std::max(best, (current_sum - u) * current_product / total_product);
            } else {
                best = std::max(best, (u - current_sum) * current_product / total_product);
            }
        }

        std::cout << std::fixed << std::setprecision(20) << best << std::endl;
    }

    return 0;
}
