using namespace std;

int start[300];
int t[30];
int d[30];
int e[30][100];
bool res[(1 << 20)];

void solve() {
    int n, m, k;
    cin >> n >> m >> k;

    for (int i = 0; i < n; i++) {
        cin >> start[i];
    }

    for (int i = 0; i < m; i++) {
        cin >> t[i] >> d[i];
        for (int j = 0; j < d[i]; j++) {
            cin >> e[i][j];
        }
    }

    memset(res, false, sizeof(res));
    res[0] = true;

    for (int i = 0; i < m; i++) {
        for (int j = (1 << k) - 1; j >= 0; j--) {
            if (res[j]) {
                bool valid = true;
                for (int l = 0; l < d[i]; l++) {
                    if (start[e[i][l] - 1] < t[i]) {
                        valid = false;
                        break;
                    }
                }
                if (valid) {
                    int mask = j;
                    for (int l = 0; l < d[i]; l++) {
                        mask |= (1 << (e[i][l] - 1));
                    }
                    res[mask] = true;
                }
            }
        }
    }

    bool possible = false;
    for (int i = 0; i < (1 << k); i++) {
        if (res[i]) {
            possible = true;
            break;
        }
    }

    if (possible) {
        cout << "POSSIBLE" << endl;
    } else {
        cout << "IMPOSSIBLE" << endl;
    }
}

int main() {
    int t;
    cin >> t;

    for (int i = 1; i <= t; i++) {
        cout << "Case " << i << ": ";
        solve();
    }

    return 0;
}
