int rows, cols;
bool memo[2][100][100][1 << 16];

bool isok(int r, int c, int happy) {
    return r >= 0 && r < rows && c >= 0 && c < cols && ((happy & (1 << (r * cols + c))) == 0);
}

bool proc(bool alice, int r, int c, int happy) {
    if (memo[alice][r][c][happy]) return true;
    memo[alice][r][c][happy] = true;

    for (int dr = -1; dr <= 1; dr++) {
        for (int dc = -1; dc <= 1; dc++) {
            if (dr == 0 && dc == 0) continue;
            if (isok(r + dr, c + dc, happy)) {
                if (!proc(!alice, r + dr, c + dc, happy)) return true;
            }
        }
    }

    return false;
}

bool canWin(bool alice, int kr, int kc, int happy) {
    if (memo[alice][kr][kc][happy]) return memo[alice][kr][kc][happy];

    memo[alice][kr][kc][happy] = proc(alice, kr, kc, happy);
    return memo[alice][kr][kc][happy];
}

int main() {
    std::ifstream fin("happy.txt");
    std::ofstream fout("sad.txt");

    int t;
    fin >> t;

    for (int i = 0; i < t; i++) {
        fin >> rows >> cols;
        std::vector<std::string> grid(rows);

        memset(memo, false, sizeof(memo));

        int happy = 0, kr = -1, kc = -1;
        for (int r = 0; r < rows; r++) {
            fin >> grid[r];
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != '.') {
                    happy |= (1 << (r * cols + c));
                }
                if (grid[r][c] == 'K') {
                    kr = r;
                    kc = c;
                }
            }
        }

        if (canWin(true, kr, kc, happy)) {
            fout << "ALICE\n";
        } else {
            fout << "BOB\n";
        }
    }

    fin.close();
    fout.close();
    return 0;
}
