int n, m, k, d, dr[] = {-1, 0, 1, 0}, dc[] = {0, 1, 0, -1};
string A[505];
bool vis[505][505];
bool cn[505][505];
set<int> cndeps[505][505];
set<pair<int, int>> TUR[505][505];
int dist[505][505];
set<int> deps[505][505];

bool dfs(int u, int snk) {
    vis[u / m][u % m] = true;
    for (auto v : TUR[u / m][u % m]) {
        if (!cn[snk][v.second]) {
            cn[snk][v.second] = true;
            if (cndeps[v.first][v.second].empty() || dfs(*cndeps[v.first][v.second].begin(), v.second)) {
                cndeps[u / m][u % m].insert(v.second);
                return true;
            }
        }
    }
    return false;
}

void dfs2(int u, int v, vector<int>& asn, vector<int>& rasn) {
    vis[u / m][u % m] = true;
    asn[u] = v;
    rasn[v] = u;
    for (auto x : TUR[u / m][u % m]) {
        if (!vis[x.first][x.second])
            dfs2(x.first * m + x.second, x.second, asn, rasn);
    }
}

