            if (A[i][j] == 'S') {
                for (int l = 0; l < 4; l++) {
                    int x = i, y = j, cnt = 0;
                    while (cnt < d) {
                        x += dr[l], y += dc[l], cnt++;
                        if (x < 0 || x >= n || y < 0 || y >= m || A[x][y] == 'X')
                            break;
                        if (A[x][y] == 'T')
                            TUR[i][j].insert({x, y}), deps[x][y].insert(i * m + j), dist[x][y] = cnt;
                    }
                }
            }
        }
    }
    int matched = 0;
    for (int i = 0; i < n * m; i++) {
        if (A[i / m][i % m] == 'S') {
            memset(vis, false, sizeof vis);
            if (dfs(i, i))
                matched++;
        }
