    memset(vis, false, sizeof vis);
    for (int i = 0; i < n * m; i++) {
        if (A[i / m][i % m] == 'S' && !vis[i / m][i % m])
            dfs2(i, i, asn, rasn);
    }
    for (int i = 0; i < n * m; i++) {
        if (asn[i] != -1)
            cout << i / m << " " << i % m << " " << asn[i] << "\n";
    }
    return 0;
}
