double distance(double x, double y, double x2, double y2) {
    return sqrt((x - x2) * (x - x2) + (y - y2) * (y - y2));
}

double calc() {
    double g1max = 0, g2max = 0;
    for (int i = 0; i < n; i++) {
        double x = table[i][0], y = table[i][1], r = table[i][2];
        if (group[i] == 0) {
            for (int j = 0; j < n; j++) {
                if (group[j] == 0) {
                    double x2 = table[j][0], y2 = table[j][1], r2 = table[j][2];
                    double d = distance(x, y, x2, y2) - r - r2;
                    if (d > g1max)
                        g1max = d;
                }
            }
        } else {
            for (int j = 0; j < n; j++) {
                if (group[j] == 1) {
                    double x2 = table[j][0], y2 = table[j][1], r2 = table[j][2];
                    double d = distance(x, y, x2, y2) - r - r2;
                    if (d > g2max)
                        g2max = d;
                }
            }
        }
    }
    return min(g1max, g2max);
}

void recur(int level) {
    if (level == n) {
        gmax = min(gmax, calc());
        return;
    }
    group[level] = 0;
    recur(level + 1);
    group[level] = 1;
    recur(level + 1);
}

