LL solve() {
    int n, m;
    scanf("%d%d", &n, &m);
    LL expected = 0;
    map<int,map<int,LL> > D;
    REP(i, m) {
        int x, y, p;
        scanf("%d%d%d", &x, &y, &p);
        expected = (expected + points(y-x)*p)%MOD;
        D[x][y] += p;
    }
