    int addAdj(int u, int v) {
        adj.pb({});
        int id = sz(adj) - 1;
        adj[u].pb(id);
        adj[v].pb(id);
        return id;
    }
    void process(int L, int R, int start, int end) {
        for (int i = L; i < R; i++) {
            if (s[i] == '(') {
                start = addAdj(start, R);
            } else {
                end = addAdj(L, end);
            }
        }
    }
    int LX, RX;
    ll result;
    void extend(vector<bool> &P) {
        queue<int> q;
        for (int i = 0; i < sz(adj); i++) {
            if (P[i]) {
                q.push(i);
            }
        }
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            P[u] = false;
            for (int v : adj[u]) {
                if (P[v]) {
                    q.push(v);
                    P[v] = false;
                }
            }
        }
    }
    void extend(ll &mask) {
        vector<bool> P(sz(adj));
        for (int i = 0; i < sz(adj); i++) {
            P[i] = mask & (1LL << i);
        }
        extend(P);
        mask = 0;
        for (int i = 0; i < sz(adj); i++) {
            if (P[i]) {
                mask |= (1LL << i);
            }
        }
    }
    ll getAtLen(ll mask, int len) {
        if (len == 0) {
            return 1;
        }
        extend(mask);
        ll res = 0;
        for (int i = 0; i < sz(adj); i++) {
            if (mask & (1LL << i)) {
                res += getAtLen(mask ^ (1LL << i), len - 1);
            }
        }
        return res;
    }
    void processPref(string str, int len) {
        ll mask = 0;
        for (int i = 0; i < len; i++) {
            if (str[i] == '(') {
                mask |= (1LL << LX);
            } else {
                mask |= (1LL << RX);
            }
        }
        result += getAtLen(mask, len);
    }
    void processMult(int L, int R, int base, int cur, string str, int len) {
        if (cur == len) {
            processPref(str, len);
            return;
        }
        processMult(L, R, base, cur + 1, str, len);
        if (base < R) {
            str[cur] = s[base];
            processMult(base + 1, R, base + 1, cur + 1, str, len);
        }
    }
    void run(int testid) {
        cin >> s >> LX >> RX;
        adj.clear();
        adj.pb({LX, RX});
        LX = 0, RX = 1;
        for (int i = 0; i < sz(s); i++) {
            process(LX, RX, LX, RX);
            if (s[i] == '(') {
                LX = addAdj(LX, RX);
            } else {
                RX = addAdj(LX, RX);
            }
        }
        result = 0;
        for (int len = 1; len <= sz(s); len++) {
            string str(len, '?');
            processMult(0, sz(s), 0, 0, str, len);
        }
        cout << "Case #" << testid << ": " << result << "\n";
    }
};

