            for (int k = 0; k < m; ++k) {
                if (a[j][k] == '?') {
                    int l = j - 1;
                    while (l >= 0) {
                        if (a[l][k] != '?') {
                            a[j][k] = a[l][k];
                            break;
                        }
                        --l;
                    }
                }
            }
        }

        int firstNonEmpty = -1;
        for (int j = 0; j < n; ++j) {
            bool isEmptyRow = true;
            for (int k = 0; k < m; ++k) {
                if (a[j][k] != '?') {
                    isEmptyRow = false;
                    break;
                }
            }
            if (!isEmptyRow) {
                firstNonEmpty = j;
                break;
            }
        }

        if (firstNonEmpty != -1) {
            for (int j = 0; j < firstNonEmpty; ++j) {
                a[j] = a[firstNonEmpty];
            }
        }

        cout << "Case #" << i << ":\n";
        for (const string& row : a) {
            cout << row << "\n";
        }
    }

    return 0;
}
