typedef set<string> trie;
typedef vector<trie> config_t;

trie maketrie(const string &s) {
    trie res;
    for (int i = 0; i < s.size(); ++i) {
        string cur = "";
        for (int j = i; j < s.size(); ++j) {
            cur += s[j];
            res.insert(cur);
        }
    }
    res.insert("");
    return res;
}

int numstr, numserv;
vector<trie> have;
map<config_t, int> ways;

void go(int at, config_t &cur, int anymask) {
    if (at == numstr) {
        if (anymask + 1 == (1 << numserv)) {
            ways[cur]++;
        }
        return;
    }
    for (int i = 0; i < numserv; ++i) {
        if (!(anymask & (1 << i))) continue;
        config_t next = cur;
        for (const string &s : have[at]) {
            next[i].insert(s);
        }
        go(at + 1, next, anymask);
    }
}

void solve(int testcase) {
    scanf("%d%d", &numstr, &numserv);
    have.clear();
    ways.clear();
    for (int i = 0; i < numstr; ++i) {
        string s;
        cin >> s;
        have.push_back(maketrie(s));
    }
    config_t initial(numserv);
    go(0, initial, (1 << numserv) - 1);
    int maxsz = 0, szways = 0;
    for (const auto &p : ways) {
        int cursz = 0;
        for (const trie &t : p.first) {
            for (const string &s : t) {
                cursz += s.size();
            }
        }
        if (cursz > maxsz) {
            maxsz = cursz;
            szways = p.second;
        } else if (cursz == maxsz) {
            szways += p.second;
        }
    }
    printf("Case #%d: %d %d\n", testcase, maxsz, szways);
}

int main() {
    int T;
    scanf("%d", &T);
    for (int i = 1; i <= T; ++i) {
        solve(i);
    }
    return 0;
}
