double getuy(double x) {
    int a = lower_bound(u, u + U, Point(x, -1e18)) - u;
    if (a == 0) return u[0].y;
    if (a == U) return u[U - 1].y;
    double dx = u[a].x - u[a - 1].x, dy = u[a].y - u[a - 1].y;
    return u[a - 1].y + dy / dx * (x - u[a - 1].x);
}

double getly(double x) {
    int a = lower_bound(l, l + L, Point(x, -1e18)) - l;
    if (a == 0) return l[0].y;
    if (a == L) return l[L - 1].y;
    double dx = l[a].x - l[a - 1].x, dy = l[a].y - l[a - 1].y;
    return l[a - 1].y + dy / dx * (x - l[a - 1].x);
}

