    return h[ST] != -1;
}

int dfs(int v, int f) {
    if (v == FN) return f;
    for (int& i = cur[v]; i != -1; i = nxt[i])
        if (cap[i] && h[e[i]] == h[v] + 1) {
            int df = dfs(e[i], min(f, cap[i]));
            if (df) {
                cap[i] -= df;
                cap[i ^ 1] += df;
                return df;
            }
        }
    return 0;
}

bool ok(int i, int j) {
    return i >= 0 && j >= 0 && i < n && j < m;
}

int main() {
    freopen("C-small-attempt1.in", "r", stdin);
    freopen("output.txt", "w", stdout);
    int tc;
    scanf("%d", &tc);
    for (int t = 1; t <= tc; t++) {
        int w, ht, b;
        scanf("%d%d%d", &w, &ht, &b);
        n = ht * w, m = ht * w;
        ST = n * 2, FN = n * 2 + 1;
        memset(st, -1, sizeof st);
        ecnt = 0;
        for (int i = 0; i < n; i++) {
            int x1 = i / w, y1 = i % w;
            if (x1 == 0) add_edge(ST, i, 1, 0);
            if (x1 == ht - 1) add_edge(i, FN, 1, 0);
            if (ok(x1 + 1, y1)) add_edge(i, i + w, 1, 0);
            if (ok(x1 - 1, y1)) add_edge(i - w, i, 1, 0);
            if (ok(x1, y1 + 1)) add_edge(i, i + 1, 1, 0);
            if (ok(x1, y1 - 1)) add_edge(i - 1, i, 1, 0);
        }
        for (int i = 0; i < b; i++) {
            int x1, y1, x2, y2;
            scanf("%d%d%d%d", &x1, &y1, &x2, &y2);
            x1--, y1--, x2--, y2--;
            for (int i = x1; i < x2; i++)
                for (int j = y1; j < y2; j++) {
                    int v = i * w + j;
                    cap[st[v]] = cap[st[v] ^ 1] = 0;
                }
        }
        int flow = 0;
        while (bfs()) {
            memcpy(cur, st, sizeof st);
            flow += dfs(ST, inf);
        }
        printf("Case #%d: %d\n", t, flow);
    }
    return 0;
}
