void inicializa() {
    for (int i = 2; i <= 10; i++) {
        pot[i][0] = 1;
        for (int j = 1; j < 21; j++) {
            pot[i][j] = pot[i][j - 1] * i;
        }
    }
}

int convierte(int n, int b) {
    int i = 0;
    while (n > 0) {
        number[i++] = n % b + '0';
        n /= b;
    }
    number[i] = '\0';
    return i;
}

int happy(int k, int b) {
    int sum = k, digits;
    while (sum != 1) {
        digits = convierte(sum, b);
        sum = 0;
        for (int i = 0; i < digits; i++) {
            sum += pow(number[i] - '0', 2);
        }
        if (sum == k) {
            return 0;
        }
        k = sum;
    }
    return 1;
}

int main() {
    inicializa();
    int T;
    std::cin >> T;
    while (T--) {
        std::cin >> string;
        bases = 0;
