        for (int i = 0; string[i]; i++) {
            if (string[i] == ' ') {
                B[bases++] = atoi(string + j);
                j = i + 1;
            }
        }
        B[bases++] = atoi(string + j);
        int k = 1;
        while (true) {
            bool allHappy = true;
            for (int i = 0; i < bases; i++) {
                if (!happy(k, B[i])) {
                    allHappy = false;
                    break;
                }
            }
            if (allHappy) {
                break;
            }
            k++;
        }
        std::cout << k - 1 << std::endl;
    }
    return 0;
}
