using namespace std;

int n, m, A[10][10], B[10][10];
bool used[10];

void init() {
    cin >> n;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            cin >> A[i][j];

    cin >> m;
    for (int i = 0; i < m; i++)
        for (int j = 0; j < m; j++)
            cin >> B[i][j];
}

bool makeSearch(int p) {
    if (p == m) {
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                if (A[i][j] != B[used[i]][used[j]])
                    return false;
        return true;
    }

    for (int f = 0; f < n; f++) {
        if (!used[f]) {
            used[f] = true;
            if (makeSearch(p + 1))
                return true;
            used[f] = false;
        }
    }

    return false;
}

void solve() {
    memset(used, false, sizeof(used));
    if (makeSearch(0))
        cout << "YES" << endl;
    else
        cout << "NO" << endl;
}

int main() {
    freopen("input.txt", "r", stdin);
    freopen("output.txt", "w", stdout);

    int t;
    cin >> t;
    while (t--) {
        init();
        solve();
    }

    return 0;
}
