using namespace std;

int n, M, t, A, B, C, D, x0, y0, ans;
int pnt[100005][2];

int main() {
    freopen("in.txt", "r", stdin);
    freopen("out.txt", "w", stdout);

    scanf("%d", &t);

    for (int tc = 1; tc <= t; tc++) {
        scanf("%d %d %d %d %d %d %d %d", &n, &A, &B, &C, &D, &x0, &y0, &M);
        memset(pnt, 0, sizeof(pnt));
        pnt[0][0] = x0;
        pnt[0][1] = y0;

        for (int i = 1; i < n; i++) {
            pnt[i][0] = (A * pnt[i - 1][0] + B) % M;
            pnt[i][1] = (C * pnt[i - 1][1] + D) % M;
        }

        ans = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                for (int k = j + 1; k < n; k++) {
                    int sum = pnt[i][0] + pnt[i][1] + pnt[j][0] + pnt[j][1] + pnt[k][0] + pnt[k][1];
                    if (sum % 3 == 0) {
                        ans++;
                    }
                }
            }
        }

        printf("Case %d: %d\n", tc, ans);
    }

    return 0;
}
